INSERT INTO "trending_locations" ("id", "name", "region", "description", "image_url", "adventure_types", "difficulty", "posts_count", "coords", "best_season", "trend_percent") VALUES
  ('b63307ee-5469-5892-b2d3-6d1a27ce653b', 'Kaçkar Dağları', 'Rize', 'Karadeniz’in çatısı. 3937 m zirvesi, buzul gölleri ve yaylalarıyla Türkiye’nin en etkileyici yüksek dağ yürüyüş bölgesi. Yaz aylarında Ayder–Kavron hattı çok yoğun; sonbahar başı en sakin dönem.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=80', '{"hiking","climbing","skiing"}', 'hard', 1240, geo_point(41.1211, 40.8356), 'Temmuz – Eylül', 32),
  ('2e3420f9-2b80-5b25-a255-035f75b6c1b0', 'Likya Yolu', 'Fethiye – Antalya', '540 km’lik Türkiye’nin ilk uzun mesafe yürüyüş rotası. Antik kentler, koylar ve Toroslar tek parkurda. Ölüdeniz–Kabak etabı yeni başlayanlar için ideal.', 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=1200&q=80', '{"hiking","paragliding"}', 'moderate', 2860, geo_point(29.135, 36.51), 'Mart – Mayıs, Ekim – Kasım', 18),
  ('2fa9c1ba-b2bf-52e1-a519-2ddfd6d3de33', 'Geyikbayırı', 'Antalya', 'Avrupa’nın en iyi kış tırmanış destinasyonlarından biri. 1000’den fazla rota, kireçtaşı, 4a’dan 9a’ya kadar her seviye.', 'https://images.unsplash.com/photo-1522163182402-834f871fd851?auto=format&fit=crop&w=1200&q=80', '{"climbing","hiking"}', 'extreme', 980, geo_point(30.52, 36.94), 'Ekim – Nisan', 41),
  ('40b8c219-8ffd-5ec6-8f23-26c071c44e36', 'Kaş', 'Antalya', 'Akdeniz’in en iyi dalış noktaları. Uçak batığı, Kanyon ve Fener Adası dalışları; görüş çoğu gün 25 m üzeri.', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=80', '{"diving","hiking"}', 'moderate', 1530, geo_point(29.64, 36.2), 'Mayıs – Ekim', 25),
  ('2e46086b-ce24-5214-9b21-10bbbaa1ac33', 'Erciyes', 'Kayseri', 'Orta Anadolu’nun 3917 m’lik volkanik devi. Geniş pistler, freeride alanları ve tur kayağı için uzun sezon.', 'https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1200&q=80', '{"skiing","climbing"}', 'hard', 720, geo_point(35.447, 38.532), 'Aralık – Nisan', 57),
  ('b78d6f4a-f2b1-5c3c-a898-7fea8dfa054a', 'Kapadokya', 'Nevşehir', 'Peribacaları arasında gravel ve dağ bisikleti rotaları. Sabah balonların altında sürüş, akşam vadi yürüyüşleri.', 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?auto=format&fit=crop&w=1200&q=80', '{"cycling","hiking"}', 'moderate', 2110, geo_point(34.828, 38.643), 'Nisan – Haziran, Eylül – Ekim', 12),
  ('026fce70-2d3b-5b90-9b69-39b3114d6525', 'Babadağ', 'Fethiye', 'Dünyanın en iyi yamaç paraşütü kalkış noktalarından biri. 1969 m’den Ölüdeniz’e 30–40 dakikalık uçuşlar.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=1200&q=80', '{"paragliding","hiking"}', 'hard', 1890, geo_point(29.19, 36.55), 'Nisan – Kasım', 22),
  ('bf3faf37-9222-563f-92a9-57cb7ec9ea37', 'Aladağlar', 'Niğde – Adana', 'Türkiye’nin Alpleri. Demirkazık (3756 m) ve Emler kuzey yüzleri, kış tırmanışı ve buz için en ciddi alan.', 'https://images.unsplash.com/photo-1483728642387-6c3bdd6c93e5?auto=format&fit=crop&w=1200&q=80', '{"climbing","hiking","skiing"}', 'extreme', 640, geo_point(35.15, 37.82), 'Haziran – Eylül (yaz), Ocak – Mart (buz)', 29)
INSERT INTO "hazards" ("id", "type", "severity", "status", "title", "description", "location_name", "coords", "radius_m", "reporter_id", "confirmations", "created_at", "expires_at", "resolved_at") VALUES
  ('078a5e6f-664c-5ec6-9f86-35c087261d20', 'rockfall', 'critical', 'active', 'Belgrad Ormanı — Kömürcü Bendi patikasında kaya düşmesi', 'Bent üstündeki yamaçtan düzenli kaya kopmaları var. Sabah saatlerinde iki büyük parça patikaya düştü. Alternatif olarak alt yolu kullanın, kask takın.', 'Belgrad Ormanı, Sarıyer', geo_point(28.99, 41.185), 300, '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 7, '2026-09-06T14:47:55.061Z', '2026-09-09T19:47:55.061Z', NULL),
  ('4caf219f-27fb-579a-9e3f-eb375ddf3a81', 'wildlife', 'high', 'active', 'Polonezköy — yaban domuzu sürüsü', 'Akşam saatlerinde parkur girişinde 6–7 domuz görüldü. Yavrular varsa yaklaşmayın, gürültü yapmadan geri çekilin.', 'Polonezköy Tabiat Parkı, Beykoz', geo_point(29.12, 41.11), 800, '6409e0a5-8056-5d47-8813-4457fd495efe', 3, '2026-09-06T05:47:55.061Z', '2026-09-08T19:47:55.061Z', NULL),
  ('07b6a839-11c2-54f7-949a-0b4b16926961', 'weather', 'high', 'active', 'Uludağ zirve — fırtına uyarısı', 'Meteoroloji 2 gün boyunca 90 km/s rüzgar bekliyor. Zirve platosuna çıkmayın; teleferik üstü kapalı.', 'Uludağ, Bursa', geo_point(29.22, 40.07), 3000, '75660a3a-ac38-55a0-be2f-fa317f1404b8', 11, '2026-09-05T23:47:55.061Z', '2026-09-08T11:47:55.061Z', NULL),
  ('8f4c7f88-901d-51f9-a5dc-a59f9556a378', 'avalanche', 'critical', 'active', 'Erciyes Tekir kuzey yamaç — çığ riski 4/5', 'Son 48 saatte 60 cm taze kar, rüzgar tablası oluştu. Pist dışı tüm kuzey yamaçlar kapalı sayılmalı.', 'Erciyes, Kayseri', geo_point(35.46, 38.54), 2500, '3ab76f29-6c62-5ce7-b20e-70dba73f0545', 5, '2026-09-05T19:47:55.061Z', '2026-09-07T19:47:55.061Z', NULL),
  ('588a6155-05f0-548e-b709-e100439259bd', 'trail_damage', 'medium', 'active', 'Likya Yolu Faralya inişi — köprü çökmüş', 'Kabak koyuna inen ahşap köprü çökmüş. Dere geçişi diz seviyesinde, bastonla geçilebilir.', 'Faralya, Fethiye', geo_point(29.14, 36.5), 200, '123eb7ed-5eb9-59e7-9cc3-05ae328efcb4', 9, '2026-09-03T19:47:55.061Z', NULL, NULL),
  ('e59b9dc8-d996-58ae-aa16-789540df34cb', 'flood', 'medium', 'active', 'Ağva — Yeşilçay kıyı yolu su altında', 'Yağış sonrası sahil yolu 40 cm su. Bisikletle geçiş önerilmez, iç yoldan dolaşın.', 'Ağva, Şile', geo_point(29.85, 41.14), 500, '3b5857a2-0eaf-5c3b-8a53-0a8b0d62e727', 2, '2026-09-06T10:47:55.061Z', '2026-09-08T01:47:55.061Z', NULL),
  ('1af0d57d-fdc5-5161-b91d-a56dedcd9eef', 'closure', 'low', 'active', 'Geyikbayırı Sarkıt sektörü — kuş üreme dönemi kapalı', 'Her yıl olduğu gibi Mart–Haziran arası Sarkıt kapalı. Diğer sektörler açık.', 'Geyikbayırı, Antalya', geo_point(30.525, 36.945), 400, '0249f116-7051-5a9e-adc8-7e7d94efdc68', 4, '2026-08-31T19:47:55.061Z', NULL, NULL),
  ('c2ca0f20-e871-5cb8-af89-4ac7d1e5c73c', 'rockfall', 'high', 'resolved', 'Aladağlar Demirkazık yaklaşımı — kaya düşmesi', 'Taş düşmesi durdu, yol temizlendi.', 'Aladağlar, Niğde', geo_point(35.15, 37.82), 300, '7c3e3894-19ae-5413-8501-6d3b62279984', 6, '2026-08-25T19:47:55.061Z', NULL, '2026-08-29T19:47:55.061Z')
