  ('3c5769ca-18a7-5a73-bfd8-b5d8cb20287f', '4adb07bd-2ca6-55d5-a7e3-80bfd686cb5a', 'Drone ile Ölüdeniz kıyı hattı — havadan canlı', 'DJI Mavic ile Babadağ inişinden Ölüdeniz lagününe.', 'paragliding', 'live', 'Ölüdeniz, Fethiye', geo_point(29.12, 36.55), 512, 530, 940, 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80', 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8', NULL, '2026-09-06T19:35:55.174Z', NULL, 380, 'drone', '{"altitudeM":380,"speedKmh":34,"batteryPct":68,"headingDeg":215,"distanceFromPilotM":1240}'::jsonb),
  ('13f3f344-7136-5d8b-a205-19bc462b11b6', 'c762e30b-24ec-516b-ba4b-51f252349c94', 'Ağrı Dağı 4200 m kampından canlı — gece çıkışı öncesi', 'Yarın 02:00 zirve çıkışı. Ekipman kontrolü ve hava durumunu birlikte değerlendiriyoruz.', 'climbing', 'live', 'Ağrı Dağı, Iğdır', geo_point(44.3, 39.7), 1284, 1510, 3420, 'https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80', 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8', NULL, '2026-09-06T19:00:55.061Z', NULL, 4200, 'camera', NULL),
  ('cd2a760a-d358-5b9a-bdbc-2a3f4bafef48', '6f80f3f6-a0da-5ea0-ac9d-1b8f4788354b', 'Kaş Kanyon dalışı — sualtı canlı', 'Kaplumbağa görürsek şanslı günümüz. Görüş 25 m.', 'diving', 'live', 'Kaş, Antalya', geo_point(29.64, 36.2), 642, 700, 1980, 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80', 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8', NULL, '2026-09-06T19:29:55.061Z', NULL, -18, 'camera', NULL),
  ('730c3f41-f4c8-5145-8bd3-b0af4621b716', '4adb07bd-2ca6-55d5-a7e3-80bfd686cb5a', 'Babadağ 1969 m kalkış — tandem uçuş', 'Termikler güçlü, Ölüdeniz üstünde 40 dk hedefliyoruz.', 'paragliding', 'live', 'Babadağ, Fethiye', geo_point(29.19, 36.55), 398, 420, 860, 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=800&q=80', 'https://test-streams.mux.dev/x36xhzz/x36xhzz.m3u8', NULL, '2026-09-06T19:41:55.061Z', NULL, 2150, 'camera', NULL),
  ('af1be9e9-5179-5144-b77e-86d07f49649d', '123eb7ed-5eb9-59e7-9cc3-05ae328efcb4', 'Likya Yolu 1. gün: Ölüdeniz’den Faralya’ya', 'Sabah 07:00’de Ovacık’tan başlıyoruz. Yol boyunca soru-cevap.', 'hiking', 'scheduled', 'Ölüdeniz, Fethiye', geo_point(29.12, 36.55), 0, 0, 0, 'https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=800&q=80', NULL, '2026-09-07T10:47:55.061Z', NULL, NULL, NULL, 'camera', NULL),
  ('99faaab4-1bf8-57ac-bab4-f9518daaaf06', '0249f116-7051-5a9e-adc8-7e7d94efdc68', 'Geyikbayırı — 7a+ proje denemesi', 'Trebenna sektörü, akşam serinliğinde.', 'climbing', 'scheduled', 'Geyikbayırı, Antalya', geo_point(30.52, 36.94), 0, 0, 0, 'https://images.unsplash.com/photo-1522163182402-834f871fd851?auto=format&fit=crop&w=800&q=80', NULL, '2026-09-08T01:47:55.061Z', NULL, NULL, NULL, 'camera', NULL),
  ('fafbd48d-bb7c-50d0-840a-eb472a2ab5a1', '3ab76f29-6c62-5ce7-b20e-70dba73f0545', 'Erciyes tur kayağı — Tekir Kapı’dan zirveye', 'Sezonun ilk turu. Toz kar!', 'skiing', 'ended', 'Erciyes, Kayseri', geo_point(35.447, 38.532), 0, 2140, 5210, 'https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=800&q=80', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4', NULL, '2026-09-04T19:47:55.061Z', '2026-09-04T21:22:55.061Z', 3917, 'camera', NULL),
  ('4a75af65-5a1e-54fc-8eda-07be0cc10f1c', '3b5857a2-0eaf-5c3b-8a53-0a8b0d62e727', 'Kapadokya gravel — balonların altında 62 km', 'Sabah 06:00 kalkış, Göreme–Uçhisar–Ürgüp döngüsü.', 'cycling', 'ended', 'Göreme, Nevşehir', geo_point(34.828, 38.643), 0, 860, 1730, 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?auto=format&fit=crop&w=800&q=80', 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4', NULL, '2026-09-02T19:47:55.061Z', '2026-09-02T23:17:55.061Z', 1240, 'camera', NULL)
