INSERT INTO "listings" ("id", "seller_id", "title", "description", "price_try", "category", "condition", "image_urls", "location_name", "coords", "adventure_types", "is_sold", "favorites_count", "created_at", "sold_at") VALUES
  ('47831c1b-2235-5ef6-ab67-18103fc09499', '0249f116-7051-5a9e-adc8-7e7d94efdc68', 'La Sportiva Solution — 41,5 numara', 'İki sezon kullanıldı, bir kez reçineli tabanı yenilendi. Boulder ve sport için ideal. Antalya’da elden teslim.', 3200, 'footwear', 'good', '{"https://images.unsplash.com/photo-1522163182402-834f871fd851?auto=format&fit=crop&w=800&q=80"}', 'Konyaaltı, Antalya', geo_point(30.6337, 36.8617), '{"climbing"}', false, 14, '2026-09-06T13:47:55.061Z', NULL),
  ('0038dd19-7f2b-5be0-b7be-9baa21a90114', '3ab76f29-6c62-5ce7-b20e-70dba73f0545', 'Dynafit Radical tur kayağı bağlaması + Scarpa Maestrale bot 28.5', 'Set olarak satıyorum. Bağlama 2 sezon, bot 1 sezon kullanıldı. Bot iç astarı ısıyla şekillendirilmiş.', 14500, 'equipment', 'like_new', '{"https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=800&q=80"}', 'Üsküdar, İstanbul', geo_point(29.0152, 41.0234), '{"skiing"}', false, 22, '2026-09-05T23:47:55.061Z', NULL),
  ('743a088b-d315-565f-9df7-93ddc30ecb45', '123eb7ed-5eb9-59e7-9cc3-05ae328efcb4', 'Osprey Exos 48 sırt çantası — kadın kesim', 'Likya Yolu’nu iki kez bu çantayla yürüdüm, hâlâ dimdik. Yağmurluk dahil.', 2800, 'equipment', 'good', '{"https://images.unsplash.com/photo-1501785888041-af3ef285b470?auto=format&fit=crop&w=800&q=80"}', 'Beşiktaş, İstanbul', geo_point(29.0083, 41.0422), '{"hiking"}', false, 31, '2026-09-05T19:47:55.061Z', NULL),
  ('4bf4d3b1-0f80-58ec-ae5b-ff8eeb03e498', '6f80f3f6-a0da-5ea0-ac9d-1b8f4788354b', 'Scubapro MK25 EVO regülatör seti (kiralık, günlük)', 'Kaş’ta günlük kiralık. Sertifika şart. Yeni servisli, 2 hafta önce bakımdan çıktı.', 450, 'rental', 'like_new', '{"https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=800&q=80"}', 'Kaş, Antalya', geo_point(29.6414, 36.2019), '{"diving"}', false, 9, '2026-09-04T19:47:55.061Z', NULL),
  ('f44e0413-5c0d-5172-891e-7d616b594451', '3b5857a2-0eaf-5c3b-8a53-0a8b0d62e727', 'Canyon Grail AL 7 gravel — M beden', '2024 model, 4.200 km. GRX 2x11, tubeless kurulu. Kapadokya turlarımın hepsini bununla yaptım.', 38000, 'equipment', 'good', '{"https://images.unsplash.com/photo-1517649763962-0c623066013b?auto=format&fit=crop&w=800&q=80"}', 'Şişli, İstanbul', geo_point(28.987, 41.06), '{"cycling"}', false, 47, '2026-09-03T19:47:55.061Z', NULL),
  ('37360d3c-0e78-5a33-8cba-3e508caedcb1', '7c3e3894-19ae-5413-8501-6d3b62279984', 'Petzl Nomic buz baltası (çift)', 'Aladağlar buz sezonundan sonra sattığım set. Uçları değiştirildi, tam bakımlı.', 9800, 'equipment', 'good', '{"https://images.unsplash.com/photo-1483728642387-6c3bdd6c93e5?auto=format&fit=crop&w=800&q=80"}', 'Niğde', geo_point(34.6833, 37.9667), '{"climbing"}', false, 18, '2026-09-02T19:47:55.061Z', NULL),
  ('0b17ceb8-ef27-57a5-8b69-c98f8448ddce', '6409e0a5-8056-5d47-8813-4457fd495efe', 'Arc’teryx Beta AR ceket — S, kırmızı', 'Gore-Tex Pro. Hafif kullanılmış, kol içinde küçük bir sürtünme izi var (fotoğrafta). Su geçirmezliği tam.', 12500, 'clothing', 'good', '{"https://images.unsplash.com/photo-1433086966358-54859d0ed716?auto=format&fit=crop&w=800&q=80"}', 'Bakırköy, İstanbul', geo_point(28.87, 40.98), '{"hiking","climbing","skiing"}', false, 26, '2026-09-01T19:47:55.061Z', NULL),
  ('26a3ce1f-9d1b-525b-a9f0-6e8ba0df24f8', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 'MSR Hubba Hubba NX 2 kişilik çadır', 'Üç kamp kullanıldı. Footprint dahil. Sarıyer’de elden teslim.', 8900, 'camping', 'like_new', '{"https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=800&q=80"}', 'Sarıyer, İstanbul', geo_point(29.05, 41.1667), '{"hiking"}', false, 12, '2026-08-31T19:47:55.061Z', NULL),
  ('1f2c66c5-b94b-5556-8022-efd40c53b5f4', 'c762e30b-24ec-516b-ba4b-51f252349c94', 'Garmin Fenix 7X Sapphire Solar', 'Ağrı çıkışında kullandım, kutusu ve tüm kayışları var. Ekran çiziksiz.', 21000, 'electronics', 'like_new', '{"https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=800&q=80"}', 'Ataşehir, İstanbul', geo_point(29.1244, 40.9923), '{"hiking","cycling","climbing"}', false, 39, '2026-08-30T19:47:55.061Z', NULL),
  ('22421ad2-f046-5876-8a72-a8730702b308', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'Black Diamond Half Dome kask — M/L', 'Bir sezon kullanıldı, darbe almadı.', 1200, 'equipment', 'good', '{"https://images.unsplash.com/photo-1454496522488-7a8e488e8606?auto=format&fit=crop&w=800&q=80"}', 'Kadıköy, İstanbul', geo_point(29.0293, 40.9903), '{"climbing"}', true, 5, '2026-08-22T19:47:55.061Z', '2026-08-22T19:47:55.061Z')
