INSERT INTO "instructors" ("id", "user_id", "headline", "bio", "specialties", "certifications", "rating", "review_count", "price_per_session_try", "session_duration_min", "languages", "years_experience", "location_name", "coords", "available_days", "students_count") VALUES
  ('c1e4cab5-3fab-57d1-8ddc-f8294429687b', '0249f116-7051-5a9e-adc8-7e7d94efdc68', 'Sport tırmanış & ip teknikleri eğitmeni', '12 yıldır Geyikbayırı’nda tırmanıyor, 8 yıldır eğitim veriyorum. Başlangıçtan lead tırmanışa, düşme pratiğinden çok uzunluklu rota yönetimine kadar birebir ya da küçük grup dersleri.', '{"climbing"}', '{"TDF Spor Tırmanış Antrenörü (2. Kademe)","Wilderness First Responder"}', 4.9, 128, 1500, 180, '{"Türkçe","English"}', 8, 'Geyikbayırı, Antalya', geo_point(30.52, 36.94), '{2,3,4,6,0}', 340),
  ('411091fb-75dc-5488-b3c7-e6de881f1ea6', '6f80f3f6-a0da-5ea0-ac9d-1b8f4788354b', 'PADI Divemaster · Open Water’dan Rescue’ya', 'Kaş’ın en iyi dalış noktalarında 900+ dalış. Open Water, Advanced ve Rescue kursları; sualtı fotoğrafçılığı atölyeleri.', '{"diving"}', '{"PADI Divemaster","PADI Rescue Diver","EFR Instructor"}', 5, 212, 2400, 240, '{"Türkçe","English","Deutsch"}', 10, 'Kaş, Antalya', geo_point(29.6414, 36.2019), '{1,2,3,4,5,6}', 520),
  ('1bd43231-28ff-56f7-bed0-7e10f0367f0e', '4adb07bd-2ca6-55d5-a7e3-80bfd686cb5a', 'Tandem pilotu & yamaç paraşütü başlangıç eğitmeni', '2.000+ tandem uçuş. Babadağ’da P1–P2 kursları, yer eğitimi ve ilk solo uçuşlar.', '{"paragliding"}', '{"THK Yamaç Paraşütü Eğitmeni","SIV Instructor"}', 4.8, 96, 3500, 300, '{"Türkçe","English"}', 14, 'Fethiye, Muğla', geo_point(29.1164, 36.6213), '{0,1,2,3,4,5,6}', 210),
  ('d497d55e-b299-54b7-b447-19cf7a7f3744', '7c3e3894-19ae-5413-8501-6d3b62279984', 'Kış tırmanışı, buz ve çığ güvenliği', 'Aladağlar’da doğdum. Kış dağcılığı, buz tırmanışı ve çığ farkındalığı (AST-1 denk) eğitimleri veriyorum.', '{"climbing","skiing","hiking"}', '{"TDF Yüksek İrtifa Dağcılık Eğitmeni","Avalanche Skills Training"}', 4.9, 74, 2000, 480, '{"Türkçe"}', 11, 'Niğde', geo_point(34.6833, 37.9667), '{5,6,0}', 160),
  ('5a525b22-16d5-57f9-b62e-92dc77a9e50d', '3b5857a2-0eaf-5c3b-8a53-0a8b0d62e727', 'Gravel & bikepacking koçu', 'Uzun mesafe bisiklet turları planlama, bikepacking ekipman seçimi ve tırmanış teknikleri. İstanbul çevresinde hafta sonu sürüşleri.', '{"cycling"}', '{"UCI Level 1 Coach","Bike Fit Sertifikası"}', 4.7, 58, 900, 150, '{"Türkçe","English"}', 6, 'Şişli, İstanbul', geo_point(28.987, 41.06), '{6,0}', 130),
  ('26416fd2-e433-5a7d-8239-6794bfb11b68', '123eb7ed-5eb9-59e7-9cc3-05ae328efcb4', 'Uzun mesafe yürüyüş & Likya Yolu rehberi', 'Likya Yolu’nun tamamını 3 kez tamamladım. Etap planlama, ekipman ve beslenme, çok günlük yürüyüşlere hazırlık.', '{"hiking"}', '{"Kültür ve Turizm Bakanlığı Rehber","Leave No Trace Trainer"}', 4.8, 143, 1200, 240, '{"Türkçe","English","Español"}', 9, 'Beşiktaş, İstanbul', geo_point(29.0083, 41.0422), '{3,4,5,6,0}', 410)
INSERT INTO "instructor_reviews" ("id", "instructor_id", "author_id", "rating", "content", "created_at") VALUES
  ('cd4be12e-1fc5-5dc2-afea-f0fd216d483e', 'c1e4cab5-3fab-57d1-8ddc-f8294429687b', 'c762e30b-24ec-516b-ba4b-51f252349c94', 5, 'Düşme korkumu iki derste çözdü. Sabırlı ve çok net anlatıyor.', '2026-09-02T19:47:55.061Z'),
  ('0a2a5df2-edcc-5250-bbf0-8fab1d323e83', 'c1e4cab5-3fab-57d1-8ddc-f8294429687b', '6409e0a5-8056-5d47-8813-4457fd495efe', 5, 'İlk 6a’mı Can ile çıktım. Rota seçimi ve emniyet konusunda çok titiz.', '2026-08-25T19:47:55.061Z'),
  ('33db0288-6e16-5836-8aab-febd739c2a9f', 'c1e4cab5-3fab-57d1-8ddc-f8294429687b', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 4, 'Harika bir eğitmen; ders süreleri biraz kısa gelebiliyor.', '2026-08-17T19:47:55.061Z'),
  ('4a4c53dd-d2fb-5505-b87e-e53d053ac7da', '411091fb-75dc-5488-b3c7-e6de881f1ea6', '6409e0a5-8056-5d47-8813-4457fd495efe', 5, 'Open Water’ı Zeynep ile aldım, sualtında kendimi hiç bu kadar güvende hissetmemiştim.', '2026-08-31T19:47:55.061Z'),
  ('492dded3-bb11-5b59-95f0-4145ed34a94c', '411091fb-75dc-5488-b3c7-e6de881f1ea6', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 5, 'Kanyon dalışı unutulmazdı. Brifingler çok detaylı.', '2026-08-07T19:47:55.061Z'),
  ('c615be3e-8d2f-52d2-9b0a-a700d185166d', '1bd43231-28ff-56f7-bed0-7e10f0367f0e', 'ce6b3bb9-a087-5262-9629-e997d312c231', 5, 'İlk tandem uçuşum, korkum kalmadı. Çok profesyonel.', '2026-09-03T19:47:55.061Z'),
  ('3b829d7e-46a8-57e1-8914-13c8d8dc0642', 'd497d55e-b299-54b7-b447-19cf7a7f3744', '3ab76f29-6c62-5ce7-b20e-70dba73f0545', 5, 'Çığ eğitimi hayat kurtarır. Emre’nin saha deneyimi eşsiz.', '2026-08-22T19:47:55.061Z'),
  ('23ed91d1-b923-5e22-aa08-25d9a9b64e9f', '5a525b22-16d5-57f9-b62e-92dc77a9e50d', 'c762e30b-24ec-516b-ba4b-51f252349c94', 4, 'Bikepacking kurulumumu baştan düzenledi, çok işime yaradı.', '2026-08-28T19:47:55.061Z'),
  ('0cda9eee-1499-5d33-a877-bff629446bb9', '26416fd2-e433-5a7d-8239-6794bfb11b68', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 5, 'Likya için verdiği etap planı birebir tuttu. Teşekkürler Elif!', '2026-09-04T19:47:55.061Z')
