  ('f62da70b-d767-51f0-8dfd-173972b600b8', '7c3e3894-19ae-5413-8501-6d3b62279984', 'Aladağlar Dağ Evi', 'pension', 'Demirkazık eteğinde 12 odalı dağ evi. Kahvaltı, ekipman kurutma odası, rehber ayarlama. Kış tırmanışçılarının üssü.', 'Çukurbağ, Niğde', geo_point(35.12, 37.83), 'https://images.unsplash.com/photo-1483728642387-6c3bdd6c93e5?auto=format&fit=crop&w=900&q=80', 4.8, 96, true, 1450, '{"Kahvaltı","Wi-Fi","Ekipman kurutma","Transfer","Soba"}', '{"climbing","hiking","skiing"}', NULL, '+90 388 000 00 00', 'business', true, '2026-08-08T15:47:55.174Z'),
  ('685905d6-7a92-59e6-8ffa-053ce0e5f26e', '4adb07bd-2ca6-55d5-a7e3-80bfd686cb5a', 'Kabak Glamping', 'glamping', 'Kabak Koyu’na bakan 8 lüks çadır. Likya Yolu yürüyüşçüleri için bagaj taşıma ve masaj.', 'Kabak, Fethiye', geo_point(29.139, 36.497), 'https://images.unsplash.com/photo-1504280390367-361c6d9f38f4?auto=format&fit=crop&w=900&q=80', 4.9, 143, true, 3200, '{"Kahvaltı","Deniz manzarası","Yoga","Bagaj taşıma"}', '{"hiking","paragliding"}', 'https://example.org', '+90 252 000 00 00', 'business', true, '2026-07-31T07:47:55.174Z'),
  ('f909949f-3825-53c2-b0f8-ceefde87ff35', '6f80f3f6-a0da-5ea0-ac9d-1b8f4788354b', 'Kaş Mavi Dalış Merkezi', 'dive_center', 'PADI 5 yıldızlı merkez. Günlük 2 dalış, Open Water’dan Divemaster’a kurslar, ekipman kiralama.', 'Kaş, Antalya', geo_point(29.6414, 36.2019), 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=900&q=80', 5, 212, true, NULL, '{"Ekipman kiralama","Tekne","Nitrox","Kurs"}', '{"diving"}', NULL, '+90 242 000 00 00', 'business', false, '2026-07-18T19:47:55.174Z'),
  ('ae39c157-b7cd-5c41-a9e3-b76d95fdf79b', '3b5857a2-0eaf-5c3b-8a53-0a8b0d62e727', 'Göreme Cave Suites', 'hotel', 'Peribacası içine oyulmuş 14 odalı butik otel. Sabah balon manzaralı teras, bisiklet kiralama.', 'Göreme, Nevşehir', geo_point(34.828, 38.643), 'https://images.unsplash.com/photo-1472214103451-9374bd1c798e?auto=format&fit=crop&w=900&q=80', 4.7, 388, true, 4800, '{"Kahvaltı","Wi-Fi","Teras","Bisiklet kiralama","Havaalanı transferi"}', '{"cycling","hiking"}', 'https://example.org', NULL, 'business', false, '2026-07-06T07:47:55.174Z'),
  ('cceb92b2-23ec-5284-973d-33ca80b90c1e', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 'Belgrad Kamp & Bungalov', 'campsite', 'Belgrad Ormanı kenarında çadır alanı ve 6 bungalov. Hafta sonu grup yürüyüşleri.', 'Sarıyer, İstanbul', geo_point(28.98, 41.18), 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=900&q=80', 4.3, 41, false, 650, '{"Duş","Ateş yeri","Otopark"}', '{"hiking","cycling"}', NULL, '+90 212 000 00 00', 'free', false, '2026-08-25T07:47:55.174Z'),
  ('77063517-64fa-548e-bdff-fa3fae1b0a51', 'c762e30b-24ec-516b-ba4b-51f252349c94', 'Summit Outdoor Store', 'shop', 'Kadıköy’de teknik ekipman mağazası. Krampon, kask, ip, tur kayağı. Uzman personel, ayakkabı bot deneme duvarı.', 'Kadıköy, İstanbul', geo_point(29.03, 40.99), 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=900&q=80', 4.6, 520, true, NULL, '{"Bot deneme duvarı","Tamir","Kiralama"}', '{"climbing","hiking","skiing"}', 'https://example.org', '+90 216 000 00 00', 'business', false, '2026-06-15T11:47:55.174Z'),
  ('30caf4a7-a7e7-5b18-9432-e28e69782738', '3ab76f29-6c62-5ce7-b20e-70dba73f0545', 'Erciyes Ski Rental', 'rental', 'Tekir Kapı’da kayak, snowboard ve tur kayağı kiralama; çığ ekipmanı (ABS çanta, beacon) seti.', 'Erciyes, Kayseri', geo_point(35.48, 38.55), 'https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=900&q=80', 4.5, 77, true, NULL, '{"Tur kayağı","Çığ ekipmanı","Bot ısıtma"}', '{"skiing"}', NULL, '+90 352 000 00 00', 'free', false, '2026-08-16T23:47:55.174Z'),
  ('97aa3acc-f9ba-5fe0-80ff-6289919b7482', '0249f116-7051-5a9e-adc8-7e7d94efdc68', 'Antalya Vertical Tours', 'tour_operator', 'Geyikbayırı tırmanış kampları, Köprülü rafting ve kanyoning turları. Sertifikalı rehberler.', 'Konyaaltı, Antalya', geo_point(30.63, 36.86), 'https://images.unsplash.com/photo-1522163182402-834f871fd851?auto=format&fit=crop&w=900&q=80', 4.9, 164, true, NULL, '{"Transfer","Ekipman dahil","Sigorta"}', '{"climbing","rafting","hiking"}', 'https://example.org', '+90 242 000 00 01', 'business', true, '2026-07-22T23:47:55.174Z')
