INSERT INTO "crags" ("id", "name", "location_name", "country_code", "coords", "rock_type", "description", "image_url", "climb_types", "route_count", "verification", "seasons", "approach_min", "updated_at") VALUES
  ('435f3bab-a4ae-59bc-800d-44c6c868a2de', 'Geyikbayırı', 'Antalya, Türkiye', 'TR', geo_point(30.5289, 36.9797), 'Kireçtaşı', 'Türkiye''nin en büyük spor tırmanış bölgesi. Sarkıtlı mağara duvarları, tüf kolonlar ve 1200''den fazla bolt''lu rota. Kış güneşi, kamp alanları ve uluslararası topluluk.', 'https://images.unsplash.com/photo-1522163182402-834f871fd851?auto=format&fit=crop&w=1200&q=80', '{"sport","multipitch"}', 12, 'verified', '{10,11,12,1,2,3,4}', 10, '2026-09-03T19:47:55.177Z'),
  ('f2df3937-10ba-59b9-a50e-3dbfb691c1cb', 'Olympos / Çıralı', 'Kemer, Antalya', 'TR', geo_point(30.4735, 36.4121), 'Kireçtaşı', 'Antik kentin hemen üzerinde deniz manzaralı spor tırmanış. Sabah gölge, öğleden sonra plaj. Kısa ve dik rotalarda teknik tutuş.', 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=80', '{"sport"}', 6, 'verified', '{10,11,12,1,2,3,4}', 15, '2026-08-25T19:47:55.177Z'),
  ('b488a4b1-1abd-5c77-b3c8-9731e944aca0', 'Ballıkayalar', 'Gebze, Kocaeli', 'TR', geo_point(29.4243, 40.8342), 'Kireçtaşı', 'İstanbul''a en yakın kanyon tırmanışı. Kısa yaklaşım, gölgeli dar vadi, 5a–8a arası 200''e yakın rota. Hafta sonu kalabalık olabilir.', 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=80', '{"sport","trad"}', 7, 'community', '{3,4,5,9,10,11}', 20, '2026-08-31T19:47:55.177Z'),
  ('0592dd0d-8bd7-5bf4-ba13-94569b5867f3', 'Kazıklıali', 'Aladağlar, Niğde', 'TR', geo_point(35.1497, 37.8231), 'Kireçtaşı (alpin)', 'Aladağlar''ın 400 metrelik büyük duvarları. Çok uzun geleneksel ve karışık rotalar, alpin yaklaşım, ani hava değişimi. Deneyim ve tam donanım gerektirir.', 'https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1200&q=80', '{"multipitch","trad","alpine"}', 6, 'verified', '{6,7,8,9}', 180, '2026-08-07T19:47:55.177Z'),
  ('1df68355-18f3-5e85-903c-edf72555ea25', 'Datça', 'Datça, Muğla', 'TR', geo_point(27.6806, 36.7216), 'Kireçtaşı', 'Yarımadanın koylarına bakan yeni geliştirilmiş sektörler. Rüzgârlı, deniz kokulu, sakin. Rotaların çoğu son iki yılda boltlandı.', 'https://images.unsplash.com/photo-1517649763962-0c623066013b?auto=format&fit=crop&w=1200&q=80', '{"sport"}', 4, 'unverified', '{10,11,12,1,2,3,4}', 25, '2026-09-04T19:47:55.177Z'),
  ('8df3f5fd-cff7-53ee-94f5-433cdd000e21', 'Kapadokya Boulder', 'Ürgüp, Nevşehir', 'TR', geo_point(34.8289, 38.6431), 'Tüf (volkanik)', 'Peri bacaları arasında yumuşak volkanik tüf blokları. Tutuşlar kırılgan olabilir; kuru havada tırman, kalın pad taşı.', 'https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=1200&q=80', '{"boulder"}', 5, 'community', '{4,5,6,9,10}', 5, '2026-08-28T19:47:55.177Z'),
  ('76d37746-577d-56cd-9ccc-bdf19ba05489', 'Karakaya', 'Çubuk, Ankara', 'TR', geo_point(32.6551, 39.8542), 'Andezit', 'Ankara''nın hafta içi akşam kayası. Kısa andezit duvarlar ve blok bahçesi; kentten 40 dakika. Topluluk tarafından yeni belgeleniyor.', 'https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1200&q=80', '{"sport","boulder"}', 4, 'unverified', '{3,4,5,6,9,10,11}', 10, '2026-09-05T19:47:55.177Z'),
  ('08c3429c-e7e8-5a4f-9cd5-6f7469cbb279', 'Kalymnos', 'Dodecanese, Yunanistan', 'GR', geo_point(26.9833, 36.9833), 'Kireçtaşı', 'Akdeniz''in spor tırmanış başkenti. Grande Grotta''nın sarkıtları, 3000''den fazla rota, mükemmel bolt kalitesi ve Bodrum''dan feribotla ulaşım.', 'https://images.unsplash.com/photo-1483728642387-6c3bdd6c93e5?auto=format&fit=crop&w=1200&q=80', '{"sport","multipitch"}', 9, 'verified', '{3,4,5,9,10,11}', 20, '2026-08-22T19:47:55.177Z'),
  ('19f6db0f-a339-5add-b2ba-19b29deb4877', 'Fontainebleau', 'Île-de-France, Fransa', 'FR', geo_point(2.6014, 48.4047), 'Kumtaşı', 'Boulder''ın doğduğu orman. Renkli devreler, sürtünme tırmanışı ve on binlerce problem. Yağmurdan sonra en az bir gün bekle — kumtaşı ıslakken kırılır.', 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80', '{"boulder"}', 8, 'verified', '{10,11,12,1,2,3,4,5}', 5, '2026-08-17T19:47:55.177Z'),
  ('997ff5d1-2a61-5934-87b7-4bba16e778f7', 'Yosemite', 'California, ABD', 'US', geo_point(-119.6008, 37.7338), 'Granit', 'Büyük duvar tırmanışının tapınağı. El Capitan, Half Dome ve Camp 4''ün efsanevi blokları. Çatlak tekniği, uzun geleneksel rotalar ve izin sistemi.', 'https://images.unsplash.com/photo-1472396961693-142e6e269027?auto=format&fit=crop&w=1200&q=80', '{"trad","multipitch","alpine","boulder"}', 8, 'verified', '{5,6,9,10}', 30, '2026-07-28T19:47:55.177Z')
