INSERT INTO "climbing_routes" ("id", "crag_id", "sector_id", "name", "type", "grade", "grade_system", "length_m", "pitches", "bolts", "stars", "first_ascent", "description", "ascent_count", "verification", "confirmations", "submitted_by", "created_at") VALUES
  ('3bb3d75c-1b2b-52e2-abd6-12a3058bee38', '435f3bab-a4ae-59bc-800d-44c6c868a2de', 'a99b1651-9342-5499-a635-3ad412b5f206', 'Trebenna Klasiği', 'sport', '6a', 'french', 25, 1, 10, 4, 'Öztürk Kayabaşı, 2003', 'Sektörün ısınma klasiği. Alt bölümde tutuşlu plaka, üstte kısa bir sarkıt geçişi. Zinciri görmeden pes etme.', 412, 'verified', 5, NULL, '2025-08-02T19:47:55.177Z'),
  ('36120d20-433a-595f-9e35-4d8816323902', '435f3bab-a4ae-59bc-800d-44c6c868a2de', 'a99b1651-9342-5499-a635-3ad412b5f206', 'Kırmızı Şafak', 'sport', '6c+', 'french', 28, 1, 12, 4, 'Ferhat Kayış, 2005', 'Kızıl renkli dikey duvar; küçük cepler ve uzun hamleler. Krux 7. bolt civarında.', 188, 'verified', 5, NULL, '2025-08-02T19:47:55.177Z'),
  ('b9ed3d78-1ff9-5521-a956-96b278c8790a', '435f3bab-a4ae-59bc-800d-44c6c868a2de', 'a99b1651-9342-5499-a635-3ad412b5f206', 'Sunset Boulevard', 'sport', '7a+', 'french', 30, 1, 13, 5, 'Alex Schwarz, 2006', 'Tüf kolonlarında dans. Sürekli zorlukta, dayanıklılık rotası. Bölgenin en güzel 7a+’sı.', 143, 'verified', 5, NULL, '2025-08-02T19:47:55.177Z'),
  ('5d7835fc-d352-5dcc-98de-6d127757582e', '435f3bab-a4ae-59bc-800d-44c6c868a2de', 'a580e55e-0d7c-5dda-b83e-07e7c3dfe2b0', 'Sarkıt Kralı', 'sport', '7c', 'french', 24, 1, 11, 5, 'Öztürk Kayabaşı, 2004', 'Mağara tavanından sarkan tüf sarkıtlarına diz kilidi. Güçlü ve üç boyutlu tırmanış.', 61, 'verified', 5, NULL, '2025-08-02T19:47:55.177Z'),
  ('aeffdc4b-de2b-5fdc-82df-17d3aa2f9e4a', '435f3bab-a4ae-59bc-800d-44c6c868a2de', 'a580e55e-0d7c-5dda-b83e-07e7c3dfe2b0', 'Damla', 'sport', '6b', 'french', 20, 1, 8, 3, NULL, 'Mağara girişinin sağında, kısa ama hafif sarkık. Akşam nemi tutuşları kaygan yapar.', 230, 'verified', 5, NULL, '2025-08-02T19:47:55.177Z'),
