INSERT INTO "stay_reviews" ("id", "business_id", "booking_id", "author_id", "rating", "text", "verified_stay", "created_at") VALUES
  ('2d397246-f8e8-5b4a-919f-a51f3fe6e4ac', 'f62da70b-d767-51f0-8dfd-173972b600b8', '833b7d17-317b-51f5-bc91-4df2e155d7fb', '123eb7ed-5eb9-59e7-9cc3-05ae328efcb4', 5, 'Demirkazık için mükemmel üs. Sabah 4’te kahvaltı hazırladılar, ekipman kurutma odası hayat kurtardı.', true, '2026-08-02T19:47:55.184Z'),
  ('6a1b46cf-c743-52cf-ba1b-b19b54cbeb82', 'f62da70b-d767-51f0-8dfd-173972b600b8', '43a27824-c414-5cfd-b593-14dda0b60e07', '0249f116-7051-5a9e-adc8-7e7d94efdc68', 4, 'Odalar sade ama sıcak. Soba gece boyu yanıyor. Wi-Fi zayıf — zaten dağa geliyorsun.', true, '2026-07-08T19:47:55.184Z'),
  ('c943897a-36f9-5955-a222-f036271ba639', '685905d6-7a92-59e6-8ffa-053ce0e5f26e', '0f4e4401-67f8-5185-897f-9e974259b604', '6f80f3f6-a0da-5ea0-ac9d-1b8f4788354b', 5, 'Likya Yolu sonrası bu manzara ödül gibi. Bagaj taşıma servisi kusursuz çalıştı.', true, '2026-08-21T19:47:55.184Z'),
  ('b93dd9e1-b929-583c-8568-e7775a2ff492', '685905d6-7a92-59e6-8ffa-053ce0e5f26e', '06f53480-7a1d-53d9-9f45-77ef48fed359', '6409e0a5-8056-5d47-8813-4457fd495efe', 4, 'Çadırlar lüks, yoga sabahları harika. Koya iniş dik, dizlerinize dikkat.', true, '2026-07-20T19:47:55.184Z'),
  ('649c2a5b-fb00-5d5b-8e10-1ed879007e4c', 'ae39c157-b7cd-5c41-a9e3-b76d95fdf79b', 'd33e5aa1-c165-5654-a088-3c075871e4ed', '3ab76f29-6c62-5ce7-b20e-70dba73f0545', 5, 'Terastan balonları izlemek için erken kalkmaya değer. Bisiklet kiralayıp vadileri gezdik.', true, '2026-08-15T19:47:55.184Z'),
  ('c24f6676-b3db-578b-a9c6-0b1ee7a373b7', 'ae39c157-b7cd-5c41-a9e3-b76d95fdf79b', 'bc2d605c-ee95-5701-8917-25cd7dcb3390', '3b5857a2-0eaf-5c3b-8a53-0a8b0d62e727', 4, 'Mağara oda serin ve sessiz. Kahvaltı çeşitli; fiyat sezon dışında daha makul.', true, '2026-06-28T19:47:55.184Z'),
  ('9d7364c1-664e-59fc-8c86-c85798d58de5', 'cceb92b2-23ec-5284-973d-33ca80b90c1e', '44a99366-a691-5e58-a661-a4dec7bef0e6', 'c762e30b-24ec-516b-ba4b-51f252349c94', 4, 'İstanbul’dan kaçış için ideal. Ateş yeri ve duşlar temiz, hafta sonu kalabalık olabiliyor.', true, '2026-08-23T19:47:55.184Z'),
  ('3a6ecc0c-2462-55a9-9f83-dc344db37359', 'cceb92b2-23ec-5284-973d-33ca80b90c1e', 'c697d4dd-0ae9-54af-a01c-3b415db043aa', 'ce6b3bb9-a087-5262-9629-e997d312c231', 3, 'Bungalov rahat ama karavan alanında elektrik bir gece kesildi. Personel ilgiliydi.', true, '2026-08-07T19:47:55.184Z')
