INSERT INTO "clubs" ("id", "name", "university", "city", "country_code", "description", "logo_url", "cover_url", "adventure_types", "member_count", "founded_year", "is_verified", "season_xp", "contact_email", "instagram", "created_at") VALUES
  ('5388d80d-f31a-5822-ad8d-620d29a3bc1d', 'ODTÜ Dağcılık ve Kış Sporları Topluluğu', 'ODTÜ', 'Ankara', 'TR', 'Türkiye’nin en köklü üniversite dağcılık topluluklarından biri. Her dönem temel dağcılık ve kaya tırmanışı eğitimleri, kış kampları ve Aladağlar, Kaçkar, Erciyes tırmanışları düzenliyoruz. Yeni başlayanlar için Eymir kayalıklarında hafta sonu eğitimleri.', NULL, 'https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1200&q=80', '{"climbing","hiking","skiing"}', 412, 1965, true, 8640, 'dagcilik@metu.edu.tr', 'odtudagcilik', '2022-09-07T19:47:55.180Z'),
  ('fd87ddca-ad99-5b51-a770-2b9c29b8ee85', 'Boğaziçi Üniversitesi Dağcılık Kulübü (BÜDAK)', 'Boğaziçi Üniversitesi', 'İstanbul', 'TR', 'BÜDAK, 1970’ten beri Boğaziçi öğrencilerini dağlarla buluşturuyor. Kaya tırmanışı, alpinizm, kanyon geçişleri ve uzun mesafe yürüyüşleri. Her güz dönemi 100+ kişilik “Dağcılığa Giriş” programı.', NULL, 'https://images.unsplash.com/photo-1522163182402-834f871fd851?auto=format&fit=crop&w=1200&q=80', '{"climbing","hiking"}', 386, 1970, true, 7920, 'budak@boun.edu.tr', 'budakboun', '2022-09-07T19:47:55.180Z'),
  ('c11f73c0-58d5-5668-b2d9-5b62d78bd57b', 'İTÜ Dağcılık Kulübü', 'İTÜ', 'İstanbul', 'TR', 'Ayazağa kampüsünde 1978’den beri. Kaya, buz ve karışık tırmanış; Uludağ ve Kaçkar kış kampları; Ballıkayalar ve Datça tırmanış kampları. Teknik ekipman kütüphanemiz üyelere açık.', NULL, 'https://images.unsplash.com/photo-1454496522488-7a8e488e8606?auto=format&fit=crop&w=1200&q=80', '{"climbing","hiking","skiing"}', 298, 1978, true, 7310, 'dagcilik@itu.edu.tr', 'itudagcilik', '2022-09-07T19:47:55.180Z'),
  ('8002fa44-08d2-535f-b3d0-32192eef510d', 'Hacettepe Üniversitesi Doğa Sporları Topluluğu (HÜDOST)', 'Hacettepe Üniversitesi', 'Ankara', 'TR', 'Yürüyüş, kamp, kaya tırmanışı ve bisiklet turları. Beytepe kampüsünden başlayan hafta içi akşam yürüyüşleri ve Köroğlu Dağları’na hafta sonu gezileri. Doğa fotoğrafçılığı atölyeleri.', NULL, 'https://images.unsplash.com/photo-1551632811-561732d1e306?auto=format&fit=crop&w=1200&q=80', '{"hiking","climbing","cycling"}', 241, 1988, true, 5480, 'hudost@hacettepe.edu.tr', 'hudost', '2023-09-07T19:47:55.180Z'),
  ('922a84b8-6f21-5e36-987f-ad3dabe3baed', 'Ege Üniversitesi Sualtı Topluluği (EÜSAT)', 'Ege Üniversitesi', 'İzmir', 'TR', 'Ege’nin berrak sularında dalış eğitimi ve deniz koruma çalışmaları. CMAS 1 ve 2 yıldız kursları, Foça ve Karaburun dalış kampları, deniz çayırı sayımı gönüllülüğü.', NULL, 'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1200&q=80', '{"diving","canoe"}', 173, 1994, true, 4260, 'eusat@ege.edu.tr', 'eusat_dalis', '2023-09-07T19:47:55.180Z'),
  ('dac7b06c-2e3c-5f58-a611-4cdc9bce4c3e', 'Bilkent Dağcılık ve Doğa Sporları Topluluğu', 'Bilkent Üniversitesi', 'Ankara', 'TR', 'Bilkent kampüsünden Aladağlar’a. Boulder salonu antrenmanları, spor tırmanış yarışmaları ve dönem sonu büyük kamp. İngilizce eğitim seçeneği ile uluslararası öğrencilere açık.', NULL, 'https://images.unsplash.com/photo-1486870591958-9b9d0d1dda99?auto=format&fit=crop&w=1200&q=80', '{"climbing","hiking"}', 205, 1990, true, 5120, 'dagcilik@bilkent.edu.tr', 'bilkentdagcilik', '2023-09-07T19:47:55.180Z'),
  ('ebf796be-e301-5cf5-9ea4-b0d78211957b', 'KTÜ Dağcılık ve Doğa Sporları Kulübü', 'Karadeniz Teknik Üniversitesi', 'Trabzon', 'TR', 'Kaçkarlar’ın kapısında bir kulüp. Yayla yürüyüşleri, Kaçkar zirve tırmanışları, Fırtına Vadisi rafting ve kış aylarında Zigana kayak günleri. Yerel rehberlerle ortak eğitimler.', NULL, 'https://images.unsplash.com/photo-1506905925346-21bda4d32df4?auto=format&fit=crop&w=1200&q=80', '{"hiking","climbing","rafting","skiing"}', 158, 1996, false, 3890, 'dagcilik@ktu.edu.tr', 'ktudagcilik', '2024-09-06T19:47:55.180Z'),
  ('98931c34-6c49-5383-a640-c696e708ab0d', 'Akdeniz Üniversitesi Dağcılık ve Tırmanış Topluluğu', 'Akdeniz Üniversitesi', 'Antalya', 'TR', 'Geyikbayırı’na 30 dakika! Türkiye’nin en büyük spor tırmanış bölgesinde her hafta sonu tırmanış, Likya Yolu etapları ve Saklıkent kanyon geçişleri. Dalış şubemiz Kaş’ta.', NULL, 'https://images.unsplash.com/photo-1522163182402-834f871fd851?auto=format&fit=crop&w=1000&q=80', '{"climbing","hiking","diving"}', 227, 1999, true, 6150, 'tirmanis@akdeniz.edu.tr', 'akdenizdagcilik', '2023-09-07T19:47:55.180Z'),
  ('68d9e0d2-82c8-599c-b5e7-4d5a27de0d0a', 'Sabancı Üniversitesi Outdoor Kulübü (SUOUT)', 'Sabancı Üniversitesi', 'İstanbul', 'TR', 'Tuzla kampüsünden doğaya: yamaç paraşütü tanıtım günleri, Kartepe kayak, Polonezköy bisiklet turları ve Ballıkayalar tırmanışları. Sürdürülebilir kamp ilkeleriyle çalışıyoruz.', NULL, 'https://images.unsplash.com/photo-1476611317561-60117649dd94?auto=format&fit=crop&w=1200&q=80', '{"hiking","paragliding","cycling","skiing"}', 134, 2004, false, 2970, 'suout@sabanciuniv.edu', 'suoutdoor', '2024-09-06T19:47:55.180Z'),
  ('073f1f37-1baf-55a4-ad60-f5a0117357bf', 'Ankara Üniversitesi Dağcılık Kulübü (ANDAK)', 'Ankara Üniversitesi', 'Ankara', 'TR', 'Tandoğan’dan Erciyes’e. Kış dağcılığı ve kar bilimi eğitimleri, çığ farkındalık atölyeleri, Hasandağı ve Erciyes kış tırmanışları. Her ay bir “kampüsten zirveye” söyleşisi.', NULL, 'https://images.unsplash.com/photo-1483728642387-6c3bdd6c93e5?auto=format&fit=crop&w=1200&q=80', '{"climbing","skiing","hiking"}', 189, 1984, true, 4730, 'andak@ankara.edu.tr', 'andak_ankara', '2023-09-07T19:47:55.180Z'),
  ('e185294b-3b24-52cc-8f6f-ecc68971ca41', 'Dokuz Eylül Üniversitesi Doğa Sporları Kulübü', 'Dokuz Eylül Üniversitesi', 'İzmir', 'TR', 'İzmir çevresinde bisiklet, yürüyüş ve kano. Bozdağ tırmanışları, Karagöl kampı, Urla bisiklet turu ve Gediz Deltası kano günleri. Şehir içi haftalık bisiklet buluşmaları.', NULL, 'https://images.unsplash.com/photo-1471506480416-7c2f3c5b8b2f?auto=format&fit=crop&w=1200&q=80', '{"cycling","hiking","canoe"}', 146, 2001, false, 3140, 'dogasporlari@deu.edu.tr', 'deudogasporlari', '2024-09-06T19:47:55.180Z'),
  ('0ca54e72-cbeb-5d89-a09a-b31c2ce818bd', 'Yıldız Teknik Üniversitesi Dağcılık Kulübü (YTÜDAK)', 'Yıldız Teknik Üniversitesi', 'İstanbul', 'TR', 'Davutpaşa ve Beşiktaş kampüslerinde iki şube. Temel dağcılık eğitimi, Uludağ kış kampı, Belgrad Ormanı akşam koşuları ve öğrenci yarışmaları. İTÜ ve BÜDAK ile ortak etkinlikler.', NULL, 'https://images.unsplash.com/photo-1519681393784-d120267933ba?auto=format&fit=crop&w=1200&q=80', '{"climbing","hiking"}', 212, 1982, true, 4010, 'ytudak@yildiz.edu.tr', 'ytudak', '2023-09-07T19:47:55.180Z'),
  ('35c3495b-3a59-5dda-a665-52ad8b17f807', 'Akademischer Alpenclub Zürich (AACZ)', 'ETH Zürich', 'Zürich', 'CH', 'Seit 1896 — ETH ve Zürih Üniversitesi öğrencilerinin alpinizm kulübü. Alpler’de haftalık tur programı, buzul kursları, kayak turu (skitour) sezonu ve kulübe ait Mischabel kulübesi.', NULL, 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7?auto=format&fit=crop&w=1200&q=80', '{"climbing","skiing","hiking"}', 520, 1896, true, 9150, 'info@aacz.ethz.ch', 'aacz_zuerich', '2022-09-07T19:47:55.180Z'),
  ('27f8709e-c87e-5a28-ad57-265a51e932e9', 'Edinburgh University Mountaineering Club (EUMC)', 'University of Edinburgh', 'Edinburgh', 'GB', 'İskoç Highlands’ın kapısında. Hafta sonu Glencoe ve Cairngorms minibüs gezileri, kış becerileri kursları, kulüp kulübesi ve her Çarşamba pub gecesi. Her seviyeye açık.', NULL, 'https://images.unsplash.com/photo-1508672019048-805c876b67e2?auto=format&fit=crop&w=1200&q=80', '{"hiking","climbing"}', 340, 1944, true, 6780, 'eumc@ed.ac.uk', 'edinburghmountaineering', '2022-09-07T19:47:55.180Z')
