INSERT INTO "club_events" ("id", "club_id", "title", "kind", "adventure_type", "description", "location_name", "coords", "starts_at", "ends_at", "capacity", "attendee_count", "open_to_all", "price_try") VALUES
  ('d5a0bf35-effb-59c8-a6e8-b56671392f2a', 'c11f73c0-58d5-5668-b2d9-5b62d78bd57b', 'Ballıkayalar Temel Kaya Eğitimi', 'training', 'climbing', 'Düğümler, emniyet, top-rope tırmanış ve iniş teknikleri. Ekipman kulüpten temin edilir. Sabah 07:00 Ayazağa çıkışı.', 'Ballıkayalar Tabiat Parkı, Gebze', geo_point(29.4406, 40.8433), '2026-08-19T08:00:00.000Z', '2026-08-19T18:00:00.000Z', 24, 24, false, 150),
  ('dfbb9c03-6fa1-509b-b91a-6a38aac5349f', '5388d80d-f31a-5822-ad8d-620d29a3bc1d', 'Eymir Kayalıkları Hafta Sonu Tırmanışı', 'trip', 'climbing', 'Yeni üyeler için Eymir’de top-rope günü. Öğle yemeği piknik.', 'Eymir Gölü, Ankara', geo_point(32.8319, 39.8261), '2026-08-25T09:00:00.000Z', '2026-08-25T17:00:00.000Z', 30, 27, true, 0),
  ('b087a53e-fd67-5b76-9657-296435e7ec81', 'fd87ddca-ad99-5b51-a770-2b9c29b8ee85', 'Dağcılığa Giriş Tanışma Söyleşisi', 'talk', 'hiking', 'BÜDAK’ın 55 yıllık hikâyesi, dönem programı ve soru-cevap. Güney Kampüs Demir Demirgil Salonu.', 'Boğaziçi Üniversitesi Güney Kampüs', geo_point(29.0507, 41.0836), '2026-08-28T18:00:00.000Z', '2026-08-28T20:00:00.000Z', NULL, 142, true, 0),
  ('883edcf9-b531-5e3d-b0be-69f42209fb49', '922a84b8-6f21-5e36-987f-ad3dabe3baed', 'Foça Deniz Çayırı Sayımı Dalışı', 'trip', 'diving', 'Posidonia sayımı gönüllü dalışı. 1 yıldız brövesi şart.', 'Foça, İzmir', geo_point(26.7564, 38.6698), '2026-08-31T08:00:00.000Z', '2026-08-31T16:00:00.000Z', 12, 11, false, 400),
  ('02ad3284-a3b2-5538-b1f6-92e45188c143', '27f8709e-c87e-5a28-ad57-265a51e932e9', 'Wednesday Pub Night', 'social', 'hiking', 'Haftalık kulüp buluşması. Hafta sonu minibüs listeleri burada açılır.', 'Teviot Row House, Edinburgh', geo_point(-3.1885, 55.9455), '2026-09-04T19:00:00.000Z', '2026-09-04T23:00:00.000Z', NULL, 58, true, 0),
  ('42af8fc2-10b0-5eb7-8e8c-4530e571d458', 'c11f73c0-58d5-5668-b2d9-5b62d78bd57b', 'Uludağ Kış Kampı Hazırlık Yürüyüşü', 'trip', 'hiking', 'Kış kampı öncesi kondisyon ve ekipman kontrol yürüyüşü. Sarıalan–Kirazlıyayla–Sarıalan, ~14 km, 700 m tırmanış. Ekipman listesi WhatsApp grubunda.', 'Uludağ Sarıalan, Bursa', geo_point(29.1352, 40.1071), '2026-09-10T07:00:00.000Z', '2026-09-10T19:00:00.000Z', 28, 21, false, 350),
  ('b76fc28a-4b55-5327-b752-387ca4ddad44', 'c11f73c0-58d5-5668-b2d9-5b62d78bd57b', 'Belgrad Ormanı Akşam Koşusu', 'social', 'hiking', 'Neşet Suyu parkuru, 8 km rahat tempo. Sonrasında çay.', 'Belgrad Ormanı, İstanbul', geo_point(28.9833, 41.1833), '2026-09-08T18:00:00.000Z', '2026-09-08T20:00:00.000Z', NULL, 17, true, 0),
  ('2a3684af-8aee-537d-8798-e4604e3d3534', 'c11f73c0-58d5-5668-b2d9-5b62d78bd57b', 'Buz Tırmanışı Teorik Eğitimi', 'training', 'climbing', 'Buz kazması, krampon, buz vidası kullanımı ve şelale buz tırmanışı temelleri. Erzurum kampı için ön koşul.', 'İTÜ Ayazağa Kampüsü, MED B-101', geo_point(29.0223, 41.1055), '2026-09-15T18:00:00.000Z', '2026-09-15T21:00:00.000Z', 40, 40, false, 0),
  ('1596cc90-ad08-54d7-b648-578cd0fb8a3a', '5388d80d-f31a-5822-ad8d-620d29a3bc1d', 'Aladağlar Demirkazık Güz Tırmanışı', 'trip', 'climbing', '3 gün 2 gece. Demirkazık (3756 m) normal rotası; en az bir kış kampı deneyimi ve kulüp onayı gerekir. Ulaşım kulüp minibüsü.', 'Aladağlar, Niğde', geo_point(35.15, 37.8), '2026-09-17T06:00:00.000Z', '2026-09-19T20:00:00.000Z', 16, 14, false, 1200),
  ('ed168626-ac2d-5b29-bc48-d953ec03b6b5', '5388d80d-f31a-5822-ad8d-620d29a3bc1d', 'Söyleşi: Kadınlar 8000’lerde', 'talk', 'climbing', 'Himalaya tırmanışları üzerine konuk konuşmacı. Kültür ve Kongre Merkezi.', 'ODTÜ KKM, Ankara', geo_point(32.7822, 39.8917), '2026-09-12T18:00:00.000Z', '2026-09-12T20:00:00.000Z', 300, 212, true, 0),
  ('c83d7eb0-5d72-5cd2-91cf-132153c7533d', 'fd87ddca-ad99-5b51-a770-2b9c29b8ee85', 'Kazdağları Sonbahar Yürüyüşü', 'trip', 'hiking', 'Hasanboğuldu–Sütüven Şelalesi–Ayazma parkuru. Yeni üyeler için ideal, 2 gün 1 gece kamp.', 'Kazdağları, Balıkesir', geo_point(26.85, 39.7), '2026-09-14T06:00:00.000Z', '2026-09-15T21:00:00.000Z', 35, 29, true, 650),
  ('f814b5db-ee19-5688-90c2-34c8aec1a6b4', 'fd87ddca-ad99-5b51-a770-2b9c29b8ee85', 'BÜDAK Boulder Ligi — 1. Etap', 'competition', 'climbing', 'Kampüs boulder duvarında 4 etaplık lig. Puan tablosu dönem sonu ödüllü.', 'Boğaziçi Kuzey Kampüs Spor Salonu', geo_point(29.0453, 41.0878), '2026-09-11T17:00:00.000Z', '2026-09-11T21:00:00.000Z', 60, 44, false, 50),
