INSERT INTO "quiz_questions" ("id", "question", "options", "answer_index", "explanation", "adventure_type") VALUES
  ('44555828-986b-5b2d-87ff-9fd6aa8dcb4d', 'Hipotermi şüphesi olan birine ilk yapılması gereken nedir?', '{"Hızla ovalamak","Rüzgârdan korumak ve ıslak giysileri değiştirmek","Sıcak duş aldırmak","Alkol vermek"}', 1, 'Islak giysiler ısı kaybını hızlandırır; önce yalıtım ve rüzgârdan koruma gelir. Ovalama ve alkol durumu kötüleştirir.', 'hiking'),
  ('23e87f44-16b4-5ffe-a490-aef5a95e5a07', 'Pusulada manyetik kuzey ile harita kuzeyi arasındaki farka ne denir?', '{"Eğim","Sapma (deklinasyon)","Azimut","Rota açısı"}', 1, 'Deklinasyon, bölgeye göre değişir ve haritanın kenarında yazar; kerteriz alırken düzeltilmelidir.', NULL),
  ('daacbc36-29af-5d67-aed5-39c2098b9559', '"Leave No Trace" ilkesine göre kamp ateşi için en doğru yaklaşım hangisidir?', '{"Yeni bir ocak açmak","Mevcut ateş yerini kullanmak ya da ocak tercih etmek","Yeşil dal toplamak","Ateşi sabaha kadar yakmak"}', 1, 'Mevcut ateş halkalarını kullanmak ya da kamp ocağı tercih etmek doğaya en az iz bırakır.', NULL),
  ('174fbd28-899f-5ceb-b32a-e373cd350909', 'Çığ tehlikesini artıran en önemli etken hangisidir?', '{"Açık ve soğuk hava","Yeni yağan yoğun kar ve rüzgâr","Düşük irtifa","Gece saatleri"}', 1, 'Kısa sürede yağan çok kar ve rüzgârla taşınan kar, zayıf tabakalar üzerinde yük oluşturur.', 'skiing'),
  ('6053cac4-bb3d-5975-9aac-b7b757c82791', 'Sekizli düğüm (figure-eight) tırmanışta en çok ne için kullanılır?', '{"İpi kısaltmak","Emniyet kemerine ip bağlamak","İki ipi eklemek","Çadır ipi germek"}', 1, 'İzlenen sekizli düğüm güvenli, kontrolü kolay ve tırmanış ipini kemere bağlamanın standart yoludur.', 'climbing'),
  ('dd009932-83d3-5d94-8931-ffb9052cdc53', 'Dalışta güvenli çıkış hızı yaklaşık kaç metre/dakikadır?', '{"3 m/dk","9 m/dk","18 m/dk","30 m/dk"}', 1, 'Çoğu eğitim kurumu 9 m/dk (ya da daha yavaş) çıkış hızını önerir; hızlı çıkış dekompresyon hastalığı riskini artırır.', 'diving'),
  ('bc6af0b6-cf1a-546e-b23a-8cbc8ea4afdf', 'Dalış sonrası uçağa binmek için önerilen en kısa bekleme süresi (tek dalış) nedir?', '{"2 saat","6 saat","12 saat","24 saat"}', 2, 'Tek dekompresyonsuz dalış sonrası en az 12 saat, tekrarlı dalışlarda 18 saat beklenmesi önerilir.', 'diving'),
  ('134daa4a-c266-5662-ad0e-c591d95e3c33', 'Yamaç paraşütünde kalkış için ideal rüzgâr nasıl olmalıdır?', '{"Arkadan ve sert","Önden, düzenli ve hafif-orta şiddette","Yandan ve ani","Hiç rüzgâr olmamalı"}', 1, 'Kanadı şişirmek ve kontrol etmek için önden gelen düzenli rüzgâr gerekir; arkadan rüzgâr çok tehlikelidir.', 'paragliding'),
  ('9e567e00-7f68-581f-8858-fd94c109a46a', 'Yıldırım riski olan bir fırtınada dağda ne yapmalısın?', '{"Zirveye devam etmek","Ağaç altına sığınmak","Sırt hattından uzaklaşıp çömelmek","Metal ekipmanı yanında tutmak"}', 2, 'Yüksek noktalardan ve yalnız ağaçlardan uzaklaş; ayakları bitişik çömel, metal ekipmanı uzağa bırak.', 'hiking'),
  ('fd216db5-7596-530a-bc56-b41c0229f89a', 'Haritada eşyükselti eğrilerinin birbirine yaklaşması ne anlama gelir?', '{"Düz arazi","Dik yamaç","Su kaynağı","Orman sınırı"}', 1, 'Eğriler ne kadar sık ise arazi o kadar diktir; seyrek eğriler düzlük gösterir.', NULL),
  ('235bac8f-5954-563e-a711-b5f4875a49dd', 'Bileği burkulan birine ilk 48 saatte hangi yaklaşım uygulanır?', '{"Sıcak kompres","Dinlenme, buz, baskı, yükseltme (RICE)","Masaj","Yürümeye devam"}', 1, 'RICE yaklaşımı şişliği ve ağrıyı azaltır; sıcak uygulama ilk günlerde şişliği artırır.', NULL),
  ('07e952d9-0d4f-51d8-b1a8-32cda9d66de5', 'Bir günlük yürüyüşte kişi başı önerilen en az su miktarı yaklaşık ne kadardır?', '{"0,5 litre","1 litre","2 litre","5 litre"}', 2, 'Sıcak ve eforlu koşullarda 2 litre alt sınırdır; su kaynaklarını önceden planla.', 'hiking'),
  ('7b2320b6-a0d4-5311-8258-b98419cd0e24', 'Rafting sırasında bottan düşersen doğru pozisyon hangisidir?', '{"Yüzükoyun yüzmek","Sırtüstü, ayaklar akış yönünde ve yukarıda","Dik durmaya çalışmak","Kayalara tutunmak"}', 1, 'Ayaklar ileride ve su yüzeyinde olursa kayalara çarpmayı ve ayak sıkışmasını önlersin.', 'rafting'),
  ('b1f5bbeb-b764-5e23-aae3-a95776a74965', 'Bisiklet ile uzun bir tırmanışta kadans nasıl olmalıdır?', '{"Düşük kadans, ağır vites","Yüksek kadans, hafif vites","Fark etmez","Ayakta pedal çevirmek zorunludur"}', 1, 'Hafif viteste yüksek kadans (80–90 rpm) kasları daha az yorar ve dizleri korur.', 'cycling'),
  ('c84fe38e-b85d-5fcd-accb-9bbc4112648a', 'Kanoda çift palalı kürek hangi disiplinde kullanılır?', '{"Kano (canoe)","Kayak","Rafting","Sup"}', 1, 'Kayakta çift palalı, kanoda tek palalı kürek kullanılır.', 'canoe'),
  ('0d512130-130f-58ee-947c-2a7e50a54a70', 'Kayak pistlerinde "siyah" işaret ne anlama gelir?', '{"Başlangıç seviyesi","Orta seviye","Zor / ileri seviye","Kapalı pist"}', 2, 'Avrupa renk sisteminde yeşil-mavi-kırmızı-siyah sırasıyla zorlaşır; siyah en zor pistlerdir.', 'skiing'),
  ('5417c258-ebaa-513c-afca-4419e8ee8204', 'Yükseklik hastalığının erken belirtisi hangisidir?', '{"Kaşıntı","Baş ağrısı, bulantı ve iştahsızlık","Görme netleşmesi","Aşırı enerji"}', 1, 'Akut dağ hastalığı baş ağrısıyla başlar; belirtiler geçmeden yükselmeye devam edilmemelidir.', 'hiking'),
  ('838f03a6-b6aa-5979-aad6-f2447841e160', 'Kızıl-turuncu bir gökyüzü akşamları genellikle ne anlama gelir?', '{"Yaklaşan fırtına","Sakin hava","Kar yağışı","Sis"}', 1, 'Batıdaki temiz hava batan güneşi kızıla boyar; "akşam kızıllığı" genellikle iyi havanın habercisidir.', NULL),
  ('a2bf6d0b-f3a6-522b-bd1d-fc9d0748b457', 'Tırmanışta "emniyet" (belay) sırasında fren eli hangi konumda olmalıdır?', '{"Serbest","Her zaman ipte","Sadece düşüşte ipte","Ceplerde"}', 1, 'Fren eli asla ipi bırakmaz; emniyet cihazı yalnızca fren eli ipteyken çalışır.', 'climbing'),
  ('c0a7c40d-fc59-5b9e-81a5-694d9646592d', 'Kancalı (prusik) düğüm ne işe yarar?', '{"İp ekler","İp üzerinde kayar, yük binince kilitlenir","Çadır kurar","İpi keser"}', 1, 'Prusik, sabit ipte tırmanmak ve kendini emniyete almak için kullanılan sürtünme düğümüdür.', 'climbing'),
  ('800d233d-e21a-5713-a097-3f651a215f69', 'Kamp yeri seçerken hangisi doğru değildir?', '{"Kuru dere yatağından uzak","Sudan en az 60 m uzakta","Yalnız ağacın hemen altında","Rüzgârdan korunaklı"}', 2, 'Yalnız ağaçlar yıldırım çeker ve dal düşme riski taşır; açık ama korunaklı bir alan seçilmelidir.', NULL),
  ('cb6c719a-00ee-5ed4-ba74-7f84d305614b', 'Dalış partnerin dip suda panikledi. İlk ne yaparsın?', '{"Yüzeye fırlarım","Göz teması kurup sakinleştirir, kontrollü çıkış yaparım","Yalnız bırakırım","Regülatörünü çıkarırım"}', 1, 'Sakinlik bulaşıcıdır; göz teması ve el işaretleriyle güven ver, birlikte kontrollü yüksel.', 'diving'),
  ('1a3b7147-bdff-5e01-aa36-dc2d854b5628', 'Acil durumda uluslararası dağ tehlike işareti nasıl verilir?', '{"Dakikada 6 sinyal, 1 dakika ara","Sürekli ıslık","Dakikada 3 sinyal","Sadece geceleri ışık"}', 0, 'Dakikada 6 kez (10 saniyede bir) ışık/ses sinyali, 1 dakika ara; yanıt dakikada 3 sinyaldir.', NULL),
  ('d884ce4b-bc72-5a70-a4fb-f1db6ae89e6b', 'Yılan ısırmasında hangisi doğrudur?', '{"Yarayı kesmek","Emmek","Uzvu hareketsiz tutup hızla sağlık kuruluşuna ulaşmak","Turnike uygulamak"}', 2, 'Kesmek, emmek ve turnike zarar verir; uzvu kalp seviyesinin altında sabitle ve yardım çağır.', NULL),
  ('552033a5-9a1d-5244-bd3a-cf69b66f05c2', 'Kar körlüğünü önlemek için ne gerekir?', '{"Şapka","UV korumalı güneş gözlüğü","Bol su","Kalın eldiven"}', 1, 'Kardan yansıyan UV ışınları korneayı yakar; UV400 gözlük ya da kar gözlüğü şarttır.', 'skiing'),
  ('7b228763-e97e-5440-9c6f-69468c6ae405', 'Rüzgâr soğuğu etkisi ne demektir?', '{"Rüzgârın nemi azaltması","Rüzgârın hissedilen sıcaklığı düşürmesi","Rüzgârın basıncı artırması","Rüzgârın kar yağdırması"}', 1, 'Rüzgâr vücuttan ısı çekişini hızlandırır; −5°C ve 40 km/sa rüzgârda hissedilen sıcaklık −15°C civarındadır.', NULL),
  ('6d45ae17-badd-50c2-8e44-27ad7eec7110', 'Kanyon geçişinde en büyük risk nedir?', '{"Güneş yanığı","Ani su baskını","Böcekler","Yükseklik hastalığı"}', 1, 'Kilometrelerce ötedeki yağış dar kanyonda dakikalar içinde seli getirebilir; hava tahminine bak.', 'rafting'),
  ('b9c8f973-7b5d-5ded-899d-8d462b0601c0', 'Yamaç paraşütünde acil paraşüt hangi durumda kullanılır?', '{"Her inişte","Kanat kontrolü tamamen kaybedildiğinde","Rüzgâr hafifleyince","Kalkışta"}', 1, 'Kurtarılamayan kapanma ya da dolanma durumunda, yeterli yükseklik varken yedek paraşüt atılır.', 'paragliding'),
  ('7fd09041-bacd-5215-9e97-f05792d0196f', 'Yaban hayvanı izleri gördüğünde "Leave No Trace" ne önerir?', '{"Yaklaşıp fotoğraf çekmek","Yiyecek bırakmak","Mesafeyi korumak ve beslememek","Sesle uzaklaştırmak"}', 2, 'Yaban hayatına uzaktan saygı göster; besleme, yaklaşma ve alışkanlıklarını değiştirme.', NULL),
  ('e83eb1e8-03fa-5afa-b0aa-a97539366ca7', 'Bisiklette gece sürüşü için hangisi zorunludur?', '{"Kulaklık","Ön beyaz, arka kırmızı ışık ve reflektör","Şort","Yedek zincir"}', 1, 'Görünür olmak hayat kurtarır: ön beyaz, arka kırmızı ışık ve reflektif giysi kullan.', 'cycling')
