INSERT INTO "destinations" ("id", "slug", "name", "region", "country_code", "type", "adventure_types", "coords", "image_url", "summary", "guide", "max_elevation_m", "typical_days", "total_distance_km", "difficulty", "best_months", "transports", "permits", "risks", "gear", "rescue_note", "insurance_required", "stage_count", "rating", "review_count", "sources", "updated_at", "budget_low_try", "budget_high_try") VALUES
  ('e48356ba-900b-5a34-985d-5a4008461997', 'everest-base-camp-trek', 'Everest Base Camp Trek', 'Khumbu, Solukhumbu', 'NP', 'trek', '{"hiking"}', geo_point(86.8253, 27.9881), 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?auto=format&fit=crop&w=1200&q=80', 'Lukla’dan Khumbu vadisi boyunca Sherpa köyleri, manastırlar ve buzul morenleri üzerinden Everest Ana Kampı (5364 m) ve Kala Patthar (5545 m). Dünyanın en ünlü teahouse treki.', 'Nasıl gidilir
INSERT INTO "destination_stages" ("id", "destination_id", "order", "name", "kind", "coords", "elevation_m", "distance_km", "duration_min", "sleeping", "facilities", "water_available", "connectivity", "note", "rest_day_recommended") VALUES
  ('7776911c-435e-5cc3-b0e2-789619d59c61', 'e48356ba-900b-5a34-985d-5a4008461997', 1, 'Lukla (Tenzing-Hillary Havalimanı)', 'trailhead', geo_point(86.7314, 27.6875), 2860, 0, 0, true, '{"teahouse","wifi","charging","ATM","helipad","hospital"}', true, '4g', 'Sabah uçuşları hava kapanmadan iner; öğleden sonra iptaller sık. İlk gün Phakding’e yürünür.', false),
  ('138857f3-09d3-5cb7-b27f-549228ccac5f', 'e48356ba-900b-5a34-985d-5a4008461997', 2, 'Phakding', 'teahouse', geo_point(86.7128, 27.7419), 2610, 8, 210, true, '{"teahouse","hot shower","wifi","charging"}', true, '4g', 'Dudh Koshi boyunca iniş ağırlıklı kısa gün; asma köprüler ve mani taşları.', false),
  ('14a7efb5-b457-59e8-a8e9-fe99f8db99e6', 'e48356ba-900b-5a34-985d-5a4008461997', 3, 'Namche Bazaar', 'village', geo_point(86.714, 27.8069), 3440, 11, 360, true, '{"teahouse","hot shower","wifi","charging","ATM","bakery","pharmacy","gear shops"}', true, '4g', 'Sagarmatha NP girişi Monjo’da. Aklimatizasyon günü: Everest View Hotel (3880 m) ya da Khumjung turu.', true),
  ('4cdcbcba-e986-53a2-a8a9-eb32ac9b9fe4', 'e48356ba-900b-5a34-985d-5a4008461997', 4, 'Tengboche Manastırı', 'teahouse', geo_point(86.7647, 27.8364), 3860, 10, 330, true, '{"teahouse","charging","bakery"}', true, '2g', 'Phunki Tenga’dan (3250 m) 600 m dik tırmanış. Ama Dablam ve Everest manzarası, sabah puja.', false),
  ('99b69ac9-4d54-5b4d-8b19-cbc4091e1f55', 'e48356ba-900b-5a34-985d-5a4008461997', 5, 'Dingboche', 'teahouse', geo_point(86.8314, 27.8925), 4410, 11, 330, true, '{"teahouse","charging","wifi (Everest Link)","bakery"}', true, 'wifi', 'İkinci aklimatizasyon günü: Nangkartshang (5083 m) tırmanışı, akşam Dingboche’ye dönüş.', true),
  ('80b9dc31-4be4-5d0f-8e93-91b29b05613a', 'e48356ba-900b-5a34-985d-5a4008461997', 6, 'Lobuche', 'teahouse', geo_point(86.8064, 27.9503), 4940, 8, 300, true, '{"teahouse","charging"}', true, 'sat_only', 'Thukla geçidinde (4830 m) Everest şehitleri anıtları. Geceleri -15 °C olağan.', false),
  ('f8601fb6-a4c3-5682-8c6b-8a9fc947009a', 'e48356ba-900b-5a34-985d-5a4008461997', 7, 'Gorak Shep', 'teahouse', geo_point(86.8281, 27.9811), 5164, 5, 180, true, '{"teahouse"}', false, 'sat_only', 'Son yerleşim; su parayla satılır. Aynı gün EBC’ye gidip dönülür, ertesi sabah Kala Patthar.', false),
  ('af8fa003-b358-5854-8646-cd47ec3f5d21', 'e48356ba-900b-5a34-985d-5a4008461997', 8, 'Everest Ana Kampı (EBC)', 'base_camp', geo_point(86.8528, 28.0025), 5364, 4, 150, false, '{}', false, 'none', 'Khumbu Buzulu üzerinde moren yolu; nisan-mayıs sezonunda ekspedisyon çadırları. Konaklama yok.', false),
  ('f7724351-91cd-5d81-a22f-f438dad9fc6a', 'e48356ba-900b-5a34-985d-5a4008461997', 9, 'Kala Patthar', 'viewpoint', geo_point(86.8283, 27.9958), 5545, 2, 150, false, '{}', false, 'none', 'Gün doğumunda Everest, Nuptse, Pumori panoraması; rotanın en yüksek noktası. Aynı gün Pheriche’ye iniş.', false),
  ('915c8ff4-4726-558c-b135-041ad8f06a63', 'e48356ba-900b-5a34-985d-5a4008461997', 10, 'Pheriche (HRA kliniği)', 'teahouse', geo_point(86.8194, 27.8956), 4371, 13, 420, true, '{"teahouse","HRA clinic","charging","helipad"}', true, '2g', 'Himalayan Rescue Association kliniği (Mart-Mayıs, Eylül-Kasım açık); ücretsiz günlük AMS semineri.', false),
  ('939106b5-20aa-5495-9da1-9ce7deaa429e', 'e48356ba-900b-5a34-985d-5a4008461997', 11, 'Namche Bazaar (dönüş)', 'village', geo_point(86.714, 27.8069), 3440, 20, 420, true, '{"teahouse","hot shower","wifi","charging","ATM"}', true, '4g', '', false),
  ('c6efcc9c-ebfb-56cb-a9f3-8cee1fe3da44', 'e48356ba-900b-5a34-985d-5a4008461997', 12, 'Lukla (dönüş)', 'trailhead', geo_point(86.7314, 27.6875), 2860, 19, 420, true, '{"teahouse","wifi","charging","helipad"}', true, '4g', 'Ertesi sabah Kathmandu/Ramechhap uçuşu; hava riskine karşı 1–2 gün tampon bırak.', false),
  ('d330c4db-76ac-5019-b030-bf605c5625f3', '40ba914d-40a8-5f79-846c-e4e891be23b6', 1, 'Besisahar', 'trailhead', geo_point(84.3753, 28.2306), 760, 0, 0, false, '{"hotel","ATM","jeep stand","ACAP checkpost"}', true, '4g', 'Kathmandu’dan 6–8 saat otobüs. Çoğu grup buradan jeep ile Chame/Manang’a atlar.', false),
  ('b12f054a-0cb1-5bd4-a64c-e318a1b86d5a', '40ba914d-40a8-5f79-846c-e4e891be23b6', 2, 'Chame', 'village', geo_point(84.2412, 28.5559), 2670, 63, 300, true, '{"teahouse","hot spring","charging","ATM","pharmacy"}', true, '4g', 'Manang bölgesi merkezi; jeep yolunun sonuna yakın. Kaplıca havuzu nehir kenarında.', false),
  ('80de0d9b-cc53-5f55-ba60-ffa5c0fbf1cd', '40ba914d-40a8-5f79-846c-e4e891be23b6', 3, 'Upper Pisang', 'village', geo_point(84.1572, 28.6208), 3300, 15, 300, true, '{"teahouse","charging","gompa"}', true, '2g', 'Annapurna II karşıda. Üst rota (Ghyaru–Ngawal) manzara ve aklimatizasyon için alt yoldan iyidir.', false),
  ('5b3dcfee-8f0a-57a7-9200-1450fe759214', '40ba914d-40a8-5f79-846c-e4e891be23b6', 4, 'Manang', 'village', geo_point(84.0167, 28.6667), 3540, 20, 420, true, '{"teahouse","HRA clinic","wifi","charging","bakery","cinema","gear rental"}', true, 'wifi', 'Aklimatizasyon günü: Ice Lake (4600 m) ya da Gangapurna gölü; HRA’nın 15:00 AMS semineri.', true),
  ('99d83f5c-28c4-5ffc-9bc8-fc7a544137fd', '40ba914d-40a8-5f79-846c-e4e891be23b6', 5, 'Yak Kharka', 'teahouse', geo_point(83.9583, 28.7194), 4050, 10, 240, true, '{"teahouse","charging"}', true, 'none', 'Kısa gün; Manang’dan sonra günde 500 m kuralı için ideal ara durak.', false),
  ('804d7fdd-f9b7-530b-9613-957f1c1e03b9', '40ba914d-40a8-5f79-846c-e4e891be23b6', 6, 'Thorong Phedi', 'teahouse', geo_point(83.9427, 28.7597), 4450, 7, 210, true, '{"teahouse","bakery"}', true, 'none', 'High Camp (4850 m) geçidi kısaltır ama uyku irtifası riskli; AMS belirtisi varsa Phedi’de kal.', false),
  ('b0693355-d551-5071-9607-c80e280d763a', '40ba914d-40a8-5f79-846c-e4e891be23b6', 7, 'Thorong La', 'pass', geo_point(83.9358, 28.7908), 5416, 6, 300, false, '{"tea shack (sezonluk)"}', false, 'none', '04:00 çıkış; rüzgâr öğleden önce artar. Kar sonrası 2014 fırtınası anısına; hava kötüyse bekle.', false),
  ('f5eb62d0-3a52-5924-8755-e1193d39962b', '40ba914d-40a8-5f79-846c-e4e891be23b6', 8, 'Muktinath', 'village', geo_point(83.8717, 28.8167), 3760, 10, 240, true, '{"hotel","hot shower","wifi","charging","temple","jeep stand"}', true, '4g', '1.650 m iniş; dizleri koru. Hindu-Budist tapınağı; Jomsom’a jeep 1,5 saat.', false),
  ('8c805c44-b591-54b2-a5f6-47f6748dde77', '40ba914d-40a8-5f79-846c-e4e891be23b6', 9, 'Jomsom', 'village', geo_point(83.7228, 28.7806), 2720, 20, 90, true, '{"hotel","airport","ATM","wifi"}', true, '4g', 'Pokhara’ya sabah uçuşu (20 dk) ya da 8–10 saat jeep/otobüs. Kali Gandaki rüzgârı öğleden sonra.', false),
  ('d5b4bd2a-e2f5-5fbb-9250-01becf44a50b', '286e1314-621f-5ddc-b0fb-c2fce538a0f1', 1, 'Nayapul / Jhinu Danda', 'trailhead', geo_point(83.7433, 28.3675), 1780, 0, 0, false, '{"jeep stand","hot spring"}', true, '4g', 'Pokhara’dan jeep 3 saat. Jhinu kaplıcaları rotanın sonunda ödül.', false),
  ('1f8e60fb-8170-5961-9c70-37be12b8466d', '286e1314-621f-5ddc-b0fb-c2fce538a0f1', 2, 'Chhomrong', 'village', geo_point(83.8203, 28.4106), 2170, 6, 240, true, '{"teahouse","hot shower","wifi","charging","bakery"}', true, '4g', 'Modi Khola vadisine giriş; son ATM/telefon sinyali burada.', false),
  ('df27e4bb-3aca-5ef1-889c-205ef7d0e852', '286e1314-621f-5ddc-b0fb-c2fce538a0f1', 3, 'Dovan', 'teahouse', geo_point(83.8483, 28.4636), 2500, 10, 330, true, '{"teahouse","charging"}', true, 'none', 'Bambu ve rododendron ormanı; sülük mevsimi (muson) dikkat.', false),
  ('102c1880-6f67-5af1-b4a7-05e2e5f37824', '286e1314-621f-5ddc-b0fb-c2fce538a0f1', 4, 'Deurali', 'teahouse', geo_point(83.8639, 28.4972), 3230, 7, 240, true, '{"teahouse"}', true, 'none', 'Hinku Mağarası geçilir; kış/ilkbaharda çığ kanalı — sabah erken geç.', false),
  ('474af54f-683a-5abb-bc30-78393d76c19a', '286e1314-621f-5ddc-b0fb-c2fce538a0f1', 5, 'Machapuchare Base Camp (MBC)', 'teahouse', geo_point(83.8814, 28.5192), 3700, 5, 180, true, '{"teahouse"}', true, 'none', 'Aklimatizasyon için ABC’ye çıkmadan bir gece burada; gün doğumu Balık Kuyruğu’nda.', false),
  ('f85e6160-c374-550d-ade4-f9ad7f9de8e1', '286e1314-621f-5ddc-b0fb-c2fce538a0f1', 6, 'Annapurna Base Camp', 'base_camp', geo_point(83.8781, 28.5306), 4130, 4, 150, true, '{"teahouse","memorial"}', true, 'none', '360° buzul amfisi: Annapurna I güney duvarı, Hiunchuli, Tent Peak. Anatoli Boukreev anıtı.', false),
