INSERT INTO "vision_history" ("id", "user_id", "situation", "observations", "risk", "advice", "avoid", "actions", "source", "confidence", "created_at", "thumbnail_uri", "question") VALUES
  ('7f146a7a-a23e-51b5-ad4c-c30ed8fa29c0', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'terrain', '{"Yaklaşık 35–40° kar yamacı; üst kısımda rüzgâr taşıması ile oluşmuş karniş.","Yamacın dibinde taze kar birikintisi ve küçük kayma izleri.","Güneş yamaca doğrudan vuruyor; kar ıslak ve ağır görünüyor."}', 'high', '{"Yamacı geçmek zorundaysan tek tek, en kısa hattan ve hızla geç.","Karnişin altından değil, sırtın kaya çıkan kısmından ilerle.","Öğleden sonra ısınma ile ıslak çığ riski artar; erken saatte geç ya da rotayı değiştir.","Grupta çığ vericileri açık, kürek ve sonda çantada erişilebilir olsun."}', '{"Yamaç altında mola verme.","Karnişin üzerine çıkma; kenar 5–10 m geride çökebilir."}', '[{"label":"Tehlike bölgeleri","href":"/hazards","icon":"triangle-alert"},{"label":"Çığ ilk yardımı","href":"/first-aid/avalanche","icon":"heart-pulse"},{"label":"Rota planlayıcı","href":"/maps/planner","icon":"route"}]'::jsonb, 'remote', 0.74, '2026-09-04T09:12:00.000Z', 'https://images.unsplash.com/photo-1517824806704-9040b037703b?auto=format&fit=crop&w=640&q=80', 'Buradan geçebilir miyim?'),
  ('6264dc3c-9c5f-5bf2-b147-ca304fc6299d', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'weather', '{"Batıda hızla yükselen kümülonimbus; tepesi örs biçimini almaya başlamış.","Alçak seviyede koyu gri tabaka bulutları; görüş azalıyor."}', 'high', '{"Sırt ve zirveden hemen in; 30–60 dakika içinde fırtına bekle.","30/30 kuralını uygula: şimşek–gök gürültüsü arası 30 sn altındaysa sığın.","Metal ekipmanı çantandan uzağa koy, açık alanda çömel."}', '{"Tek ağaç altına sığınma.","Dere yatağında bekleme; ani taşkın olabilir."}', '[{"label":"Yıldırım çarpması","href":"/first-aid/lightning","icon":"heart-pulse"},{"label":"Tehlike bölgeleri","href":"/hazards","icon":"triangle-alert"}]'::jsonb, 'remote', 0.81, '2026-08-23T13:40:00.000Z', 'https://images.unsplash.com/photo-1500674425229-f692875b0ab7?auto=format&fit=crop&w=640&q=80', 'Fırtına yaklaşıyor mu?'),
  ('515b087c-0be6-5977-8056-fb374e3b7b32', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'plant', '{"Beyaz şapkalı, halkalı ve kadehli bir mantar; Amanita cinsine benziyor.","Meşe ve kayın altında, nemli zemin."}', 'extreme', '{"Bu mantara dokunma ve kesinlikle yeme; Amanita türleri ölümcül olabilir.","Temas ettiysen ellerini sabunla yıka.","Yanlışlıkla yendiyse belirti beklemeden 112’yi ara; zehir bilgi hattı 114."}', '{"Tadına bakma.","Çocukların ve köpeklerin yaklaşmasına izin verme."}', '[{"label":"Alerjik reaksiyon","href":"/first-aid/anaphylaxis","icon":"heart-pulse"}]'::jsonb, 'remote', 0.66, '2026-08-10T16:05:00.000Z', 'https://images.unsplash.com/photo-1508802986463-d4a7b9a3d1ad?auto=format&fit=crop&w=640&q=80', 'Bu mantar yenir mi?'),
  ('c237db0f-59ec-57c4-ac6c-58e3f1b5b6de', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'water', '{"Görüntü analizi çevrimdışı yapılamadı; yerel kontrol listesi kullanıldı.","Berrak su güvenli su demek değildir; yukarı akışta hayvan ya da yerleşim varsa kirlenmiş varsay."}', 'moderate', '{"Kaynat: 1 dakika fokur fokur (3000 m üstünde 3 dakika).","Filtre: 0,2 mikron filtre bakteri ve parazitleri tutar; virüs için tablet ya da UV ekle.","Klor/iyot tableti: bekleme süresine uy (genelde 30 dk; soğuk suda 60 dk)."}', '{"Durgun, köpüklü ya da yosunlu suyu içme."}', '[{"label":"Rota planlayıcı","href":"/maps/planner","icon":"route"}]'::jsonb, 'local', 0.45, '2026-07-28T07:50:00.000Z', 'https://images.unsplash.com/photo-1502082553048-f009c37129b9?auto=format&fit=crop&w=640&q=80', 'Bu su içilir mi?')
