INSERT INTO "writer_profiles" ("user_id", "pen_name", "bio", "languages", "topics", "website", "is_verified", "follower_count", "article_count", "applied_at", "approved_at") VALUES
  ('123eb7ed-5eb9-59e7-9cc3-05ae328efcb4', 'Elif Doğan — Himalaya günlükleri', 'On yıldır yüksek irtifa trekking yapıyorum; Nepal, Ladakh ve Patagonya notlarımı gün gün yazıyorum. Yalnız seyahat eden kadınlar için pratik bilgiler öncelikli.', '{"tr","en"}', '{"trip_report","culture","guide"}', 'https://himalayagunlukleri.com', true, 4820, 3, '2025-07-13T19:47:55.805Z', '2025-07-18T19:47:55.805Z'),
  ('4adb07bd-2ca6-55d5-a7e3-80bfd686cb5a', 'Barış Çelik · Dağ fotoğrafçısı', 'Drone ve dağ fotoğrafı üzerine çalışıyorum. SHGM kuralları, pozlama ve altın saat üstüne tekniği herkesin anlayacağı dille anlatmaya çalışıyorum.', '{"tr"}', '{"photography","guide"}', 'https://bariscelik.photo', true, 2210, 3, '2025-11-10T19:47:55.805Z', '2025-11-14T19:47:55.805Z'),
  ('6f80f3f6-a0da-5ea0-ac9d-1b8f4788354b', 'Zeynep Aksoy — Mavi derinlik', 'PADI Divemaster. Kaş ve Akdeniz dalış noktaları, ekipman bakımı ve dalış güvenliği üzerine yazıyorum.', '{"tr","en"}', '{"guide","safety"}', NULL, false, 1340, 1, '2026-02-08T19:47:55.805Z', '2026-02-13T19:47:55.805Z'),
  ('c762e30b-24ec-516b-ba4b-51f252349c94', 'Kerem Aydın · Kaya günlüğü', 'Geyikbayırı ve Datça kayalarında beş yıl. Sportif tırmanışta seviye atlama, antrenman planı ve zihinsel hazırlık üstüne yazacağım.', '{"tr"}', '{"trip_report","guide"}', NULL, false, 0, 0, '2026-09-03T19:47:55.805Z', NULL),
  ('6409e0a5-8056-5d47-8813-4457fd495efe', 'Lale Demir — Hafif sırt çantası', 'Ultralight kamp ve uzun yürüyüşler. Ekipman listeleri gramıyla, rotalar gün gün. Likya Yolu, Kapadokya ve Karadeniz yaylaları ana saham.', '{"tr","en"}', '{"gear","trip_report"}', 'https://hafifsirtcantasi.com', true, 3675, 3, '2025-08-22T19:47:55.805Z', '2025-08-26T19:47:55.805Z'),
  ('0249f116-7051-5a9e-adc8-7e7d94efdc68', 'Can Yıldırım · Dağ rehberi', 'IFMGA aday rehber, TDF eğitmeni. Çığ, kış geçişleri, yüksek irtifa güvenliği ve porter hakları üzerine yazıyorum. Amaç: dağdan herkes dönsün.', '{"tr","en","de"}', '{"safety","opinion","gear"}', NULL, true, 6120, 4, '2025-04-24T19:47:55.805Z', '2025-04-26T19:47:55.805Z')
