INSERT INTO "articles" ("id", "author_id", "slug", "title", "subtitle", "cover_url", "category", "body", "tags", "destination_id", "country_code", "adventure_types", "read_minutes", "status", "likes_count", "comments_count", "views_count", "locale", "published_at", "created_at", "updated_at") VALUES
  ('647ff5c4-4e5b-51f7-b645-d9ba627ff47a', '123eb7ed-5eb9-59e7-9cc3-05ae328efcb4', 'everest-base-camp-te-12-gun-gun-gun-notlarim', 'Everest Base Camp''te 12 gün: gün gün notlarım', 'Lukla uçuşundan Kala Patthar sabahına; aklimatizasyon, konaklama ve bütçe gerçekleri.', 'https://images.unsplash.com/photo-1544735716-392fe2489ffa?auto=format&fit=crop&w=1200&q=80', 'trip_report', 'Bu yazı bir "nasıl gidilir" rehberi değil; 12 günün her sabahı defterime yazdıklarımın temize çekilmiş hali. Yine de her günün sonuna irtifa, yürüyüş süresi ve o gün ne kadar harcadığımı ekledim, çünkü planlarken en çok bu bilgileri aramıştım.
INSERT INTO "article_comments" ("id", "article_id", "author_id", "content", "created_at") VALUES
  ('05a4879e-f6fb-591a-b6e0-2500be4e30fa', '647ff5c4-4e5b-51f7-b645-d9ba627ff47a', '3ab76f29-6c62-5ce7-b20e-70dba73f0545', 'Nangkartshang uyarısı çok yerinde. Ben de aklimatizasyon gününü atlayıp Lobuche''de bir gece kâbus yaşadım, ertesi gün Dingboche''ye geri indim.', '2026-08-17T19:47:55.805Z'),
  ('9bae7894-978d-594e-9759-866c868e0a54', '647ff5c4-4e5b-51f7-b645-d9ba627ff47a', '3b5857a2-0eaf-5c3b-8a53-0a8b0d62e727', 'Bütçe kısmı için teşekkürler, tam da bunu arıyordum. Su filtresi olarak hangisini kullandınız?', '2026-08-18T19:47:55.805Z'),
  ('034c9f9a-f361-50bf-8456-875c4ad32888', '647ff5c4-4e5b-51f7-b645-d9ba627ff47a', '123eb7ed-5eb9-59e7-9cc3-05ae328efcb4', 'Squeeze tipi bir filtre; soğukta donmasın diye geceleri tulumun içinde uyudu :)', '2026-08-18T19:47:55.805Z'),
  ('287e1f3f-79a0-5ec8-a7ff-ceaa46473a43', '647ff5c4-4e5b-51f7-b645-d9ba627ff47a', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'Ramechhap uyarısı için ayrıca teşekkürler; gece 02:00 minibüsünü bilmeden gitseydim rezalet olurdu.', '2026-08-22T19:47:55.805Z'),
  ('465984b8-839b-5268-be3c-a94f638acb26', '647ff5c4-4e5b-51f7-b645-d9ba627ff47a', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 'Everest Link kartı Gorak Shep''te de çalıştı mı gerçekten? Geçen sene Lobuche''den sonra sinyal yoktu.', '2026-08-27T19:47:55.805Z'),
  ('954758ff-ab5d-515a-b8da-8f2dc3e25743', '94d03a46-d375-5680-b8bf-bcd956cae1a0', '7c3e3894-19ae-5413-8501-6d3b62279984', 'Benzinli ocak notuna katılıyorum. Kartuş -12 °C''de neredeyse hiç ısıtmadı, tersine çevirerek idare ettik.', '2026-08-07T19:47:55.805Z'),
  ('635f822a-8fb5-5ffc-a250-85dd66dcdb26', '94d03a46-d375-5680-b8bf-bcd956cae1a0', 'ce6b3bb9-a087-5262-9629-e997d312c231', 'Kar ayakkabısı hazırlığı için Uludağ''da bir gün yeterli mi sizce?', '2026-08-08T19:47:55.805Z'),
  ('6ecb20d0-a01d-5afc-95a6-65f996971a40', '94d03a46-d375-5680-b8bf-bcd956cae1a0', '0249f116-7051-5a9e-adc8-7e7d94efdc68', 'Yeterli; hatta iki saat çanta ile iniş-çıkış yapmak bile büyük fark yaratıyor. Bilek hareketini öğrenmek asıl mesele.', '2026-08-08T19:47:55.805Z'),
  ('0206adf9-c943-5cad-bee1-c0372595cf96', 'c3a731d3-4829-5208-9f78-5228037b7937', '3ab76f29-6c62-5ce7-b20e-70dba73f0545', 'Uçak batığı ilk derin dalışım olmuştu, harika seçim. Kanyon''a bir sonraki sezon.', '2026-08-26T19:47:55.805Z'),
  ('03f4a8a5-cc36-5e7d-be70-f3ad43d4ee8a', 'c3a731d3-4829-5208-9f78-5228037b7937', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'Eylül için Kaş''ta hangi merkezi önerirsiniz? Küçük grup önemli benim için.', '2026-08-28T19:47:55.805Z'),
  ('72b5aefa-b5b3-5269-ad36-b7d692479fab', 'c3a731d3-4829-5208-9f78-5228037b7937', '6f80f3f6-a0da-5ea0-ac9d-1b8f4788354b', 'İsim vermeyeyim ama limandaki merkezlerin çoğu 4 kişilik gruplarla çalışıyor; oksijen kiti sorusunu sormayı unutmayın.', '2026-08-28T19:47:55.805Z'),
  ('20992bb0-28e2-559a-8a45-40202b12282c', 'e41f173c-c9e9-50ac-95f8-4eb96e8ec00d', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 'Quilt''e geçiş için tereddütteydim; -5 °C konforda üşümediniz mi gerçekten?', '2026-07-25T19:47:55.805Z'),
  ('e6156bf6-4f95-56dc-a7ab-510cab6e353f', 'e41f173c-c9e9-50ac-95f8-4eb96e8ec00d', '6409e0a5-8056-5d47-8813-4457fd495efe', 'Sıfırın altında bir gece ceketle uyudum, onun dışında hiç sorun olmadı. Mat R değeri asıl belirleyici.', '2026-07-26T19:47:55.805Z'),
  ('a9c05116-8fe6-523d-a063-c337f1356906', '83a33671-aa95-5292-b583-c734c357ba08', '3b5857a2-0eaf-5c3b-8a53-0a8b0d62e727', 'Kadın rehber kuruluşu bilgisi çok değerli, teşekkürler. Langtang''a tek başıma gitmeye karar verdim.', '2026-07-10T19:47:55.805Z'),
  ('4465be89-6e44-518f-971e-87cfad11f0e4', '83a33671-aa95-5292-b583-c734c357ba08', 'ce6b3bb9-a087-5262-9629-e997d312c231', 'Kuduz ön aşısı konusunu kimse yazmıyor; sağlık turizmi kliniğinde 3 doz yaptırdım, iyi ki.', '2026-07-18T19:47:55.805Z'),
  ('b3beac0b-a46e-5663-b056-c9f5691d686a', 'ae323b26-ddd6-56ff-9f39-84a138803b22', 'c762e30b-24ec-516b-ba4b-51f252349c94', 'Milli park izniyle SHGM izninin ayrı olması bilgisi çok kişiyi şaşırtacak. Kaçkar için başvuru ne kadar sürdü?', '2026-08-10T19:47:55.805Z'),
  ('cd534190-b546-59e7-b27c-10aee2ed9ec1', 'ae323b26-ddd6-56ff-9f39-84a138803b22', '4adb07bd-2ca6-55d5-a7e3-80bfd686cb5a', 'Yaklaşık üç hafta; e-posta ile başvurdum, çekim tarihini ve amacını yazmak gerekiyor.', '2026-08-11T19:47:55.805Z'),
  ('cdfdd3ad-4042-569d-a884-095d2fe995ba', 'cfd6f955-f84b-5492-8b35-8030805eb3c5', '7c3e3894-19ae-5413-8501-6d3b62279984', '"Kararı en ihtiyatlı üye verir" cümlesini ekip kuralımız yaptık. Teşekkürler.', '2026-08-30T19:47:55.805Z'),
  ('33362cd8-cf95-5ede-acba-64b9314f2a47', 'cfd6f955-f84b-5492-8b35-8030805eb3c5', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'Farkındalık eğitimi için Ocak''ta yer var mı biliyor musunuz? TDF sitesinde takvim güncel değil.', '2026-09-01T19:47:55.805Z'),
  ('2e97db6f-2547-5ffc-9a4b-ffedec45ba3a', '5de50d43-971c-5890-8b7d-66101d1ce697', '3ab76f29-6c62-5ce7-b20e-70dba73f0545', 'Geçen yıl KPAP partner operatörle gittik; fiyat farkı vardı ama porterların ekipmanını görünce pişman olmadık.', '2026-07-30T19:47:55.805Z')
