INSERT INTO "doctors" ("id", "user_id", "title", "specialties", "languages", "license_no", "institution", "is_verified", "is_online", "response_min", "rating", "consult_count", "volunteer", "price_try_per_consult", "country_codes", "bio") VALUES
  ('ef1860b9-7099-5c47-8b73-0136d0420e64', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 'Uzm. Dr.', '{"toxicology","emergency"}', '{"tr","en"}', 'TR-****-4821', 'Hacettepe Üniversitesi Hastanesi — Acil Tıp', true, true, 2, 4.9, 412, true, 0, '{"TR","GE","IR"}', 'Zehirlenme ve yılan/akrep ısırıkları üzerine 11 yıl acil deneyimi. Dağcı Arama Kurtarma gönüllüsü; Kaçkarlar ve Aladağlar’da saha hekimliği yaptım.'),
  ('602b6ce6-6ac2-550c-8dd3-22ab794bb615', 'ce6b3bb9-a087-5262-9629-e997d312c231', 'Dr.', '{"wilderness","emergency"}', '{"tr","en","de"}', 'TR-****-7730', 'Uludağ Üniversitesi Tıp Fakültesi', true, true, 3, 4.8, 268, true, 0, '{"TR","DE","AT","CH"}', 'Wilderness Medicine (FAWM) sertifikalı. Hipotermi, sıcak çarpması ve uzun rotalarda tıbbi hazırlık konularında danışmanlık veriyorum.'),
  ('9d2be9b7-4c10-5ce9-b842-e27e401469c3', '6409e0a5-8056-5d47-8813-4457fd495efe', 'Prof. Dr.', '{"altitude_medicine","wilderness"}', '{"tr","en"}', 'TR-****-1194', 'Atatürk Üniversitesi — Göğüs Hastalıkları', true, true, 6, 4.9, 151, false, 900, '{"TR","NP","GE","KG"}', 'İrtifa hekimliği ve HAPE/HACE yönetimi. Ağrı, Ararat ve Himalaya ekspedisyonlarında ekspedisyon doktoru olarak görev aldım.'),
  ('67176943-f8a3-5189-b760-3e1b6404b0ad', '3b5857a2-0eaf-5c3b-8a53-0a8b0d62e727', 'Uzm. Dr.', '{"orthopedics"}', '{"tr","en","ru"}', 'TR-****-5062', 'Antalya Eğitim ve Araştırma Hastanesi', true, true, 5, 4.7, 339, false, 650, '{"TR","RU","KZ"}', 'Ortopedi ve travmatoloji uzmanı. Kırık, çıkık ve burkulmalarda sahada atelleme ve tahliye kararı konusunda destek oluyorum.'),
  ('7100d3de-89bf-5cf6-a60b-3014a09e2b7c', '3ab76f29-6c62-5ce7-b20e-70dba73f0545', 'Dr.', '{"dive_medicine","emergency"}', '{"tr","en"}', 'TR-****-8807', 'Bodrum Devlet Hastanesi — Hiperbarik Tıp', true, true, 4, 4.8, 97, true, 0, '{"TR","EG","GR"}', 'Sualtı ve hiperbarik tıp. Dekompresyon hastalığı, kulak barotravması ve dalış sonrası şikâyetlerde 7/24 basınç odası koordinasyonu.'),
  ('32e97d78-e53f-5283-9a79-5ca4c39ab14a', '7c3e3894-19ae-5413-8501-6d3b62279984', 'Uzm. Dr.', '{"dermatology","general"}', '{"tr","en","ar"}', 'TR-****-2258', 'Çukurova Üniversitesi Hastanesi', true, true, 8, 4.6, 204, false, 450, '{"TR","SA","AE"}', 'Deri hastalıkları: yanık, güneş yanığı, bitki teması (ısırgan, sumak), kene ve böcek ısırığı sonrası döküntüler.'),
  ('ad829ea0-34c3-5607-926b-743d94a8f847', '123eb7ed-5eb9-59e7-9cc3-05ae328efcb4', 'Dr.', '{"emergency","wilderness"}', '{"tr","en"}', 'TR-****-9913', 'İstanbul Şişli Etfal Eğitim ve Araştırma Hastanesi', true, false, 3, 4.8, 521, true, 0, '{"TR"}', 'Acil tıp uzmanı ve AKUT gönüllüsü. Likya Yolu boyunca yürüyüşçülere gönüllü tıbbi destek veriyorum.'),
  ('24f2360b-e314-52db-af1d-1c57cd4871c3', '0249f116-7051-5a9e-adc8-7e7d94efdc68', 'Uzm. Dr.', '{"pediatrics","general"}', '{"tr","en","de"}', 'TR-****-3376', 'Ege Üniversitesi Çocuk Hastanesi', true, false, 10, 4.7, 186, false, 550, '{"TR","DE"}', 'Çocuk sağlığı. Aile kamplarında ateş, ishal, böcek ısırığı ve küçük yaralanmalarda ebeveynlere yol gösteriyorum.'),
  ('25316b92-aca6-54ab-9524-942b3d37ca62', '6f80f3f6-a0da-5ea0-ac9d-1b8f4788354b', 'Dr.', '{"general","emergency"}', '{"tr","en","ru"}', 'TR-****-6640', 'Trabzon Kanuni Eğitim ve Araştırma Hastanesi', false, false, 12, 4.5, 73, false, 500, '{"TR","GE"}', 'Aile hekimi. Yayla ve kamp koşullarında kronik hastalık yönetimi, ilaç etkileşimleri ve genel sağlık soruları.'),
  ('20574712-0489-5d72-ba7a-46a9adbf8b86', '4adb07bd-2ca6-55d5-a7e3-80bfd686cb5a', 'Prof. Dr.', '{"toxicology","pediatrics"}', '{"tr","en","ar"}', 'TR-****-0185', 'Ankara Üniversitesi — Klinik Toksikoloji', true, false, 15, 4.9, 129, false, 800, '{"TR","IQ","SY"}', 'Klinik toksikoloji: mantar ve bitki zehirlenmeleri, akrep sokması, antivenom endikasyonları. Ulusal Zehir Danışma Merkezi eski danışmanı.')
INSERT INTO "consultations" ("id", "patient_id", "doctor_id", "urgency", "complaint", "triage", "first_aid_slug", "species_id", "coords", "status", "channel", "created_at", "accepted_at", "ended_at", "summary") VALUES
  ('dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'ef1860b9-7099-5c47-8b73-0136d0420e64', 'high', 'Arkadaşımı Kaçkar’da patikada yılan ısırdı, sağ ayak bileği. Isırık yeri şişmeye başladı, iki diş izi var. Hastaneye en az 3 saat uzaktayız.', '{"Hareketsiz tutun; ısırılan uzvu kalp seviyesinin altında sabitleyin.","Turnike YOK, kesme YOK, emme YOK, buz YOK.","Isırık saatini not edin; şişliğin sınırını kalemle işaretleyin, fotoğraf çekin.","Yüzük, saat ve dar giysileri çıkarın.","112’yi arayın; en yakın antivenom bulunan hastaneye gidin. Yılanı yakalamaya çalışmayın."}', 'snakebite', NULL, geo_point(41.1652, 40.8321), 'completed', 'chat', '2026-08-19T19:47:55.814Z', '2026-08-19T19:49:55.814Z', '2026-08-19T20:25:55.814Z', 'Doktor talimatları:
INSERT INTO "consult_messages" ("id", "consultation_id", "sender_id", "content", "image_url", "is_instruction", "created_at") VALUES
  ('168807c1-58f5-54d8-a25f-fc2b52809613', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'Arkadaşımı Kaçkar’da patikada yılan ısırdı, sağ ayak bileği. Isırık yeri şişmeye başladı, iki diş izi var. Hastaneye en az 3 saat uzaktayız.', NULL, false, '2026-08-19T19:47:55.814Z'),
  ('46275c4d-3c5b-50e1-aa7b-b2a20eb05b77', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 'Merhaba, ben Uzm. Dr. Ayşe Kurt. Şikâyetinizi okudum. Şu an nefes darlığı, dudakta morarma ya da yaygın kızarıklık var mı?', NULL, false, '2026-08-19T19:49:55.814Z'),
  ('ae0d55c4-8099-5217-a9d4-af0eabdc68fb', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'Nefes normal, sadece çok ağrıyor ve bilek şişiyor. Yılan kahverengi, zikzak desenliydi.', NULL, false, '2026-08-19T19:50:55.814Z'),
  ('2890ecd4-9f01-565f-b6b7-32d1c0c4e46f', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 'Tarif engerek ile uyumlu. Bacağı hareketsiz ve kalp seviyesinin altında tutun; turnike, kesme, emme yok. Yüzük ve saatleri hemen çıkarın.', NULL, true, '2026-08-19T19:51:55.814Z'),
  ('78bcfbce-f18f-5709-bb9b-613675ea358c', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 'Şişliğin üst sınırını kalemle işaretleyin ve saatini yazın; 15 dakikada bir aynı açıdan fotoğraf gönderin.', NULL, true, '2026-08-19T19:52:55.814Z'),
  ('e9790668-03df-5ae8-b98c-583cf5c644ca', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'İşaretledim, fotoğraf ekliyorum. Isırık saati 14:20.', 'https://images.unsplash.com/photo-1576091160550-2173dba999ef?auto=format&fit=crop&w=800&q=80', false, '2026-08-19T19:55:55.814Z'),
  ('80820a64-84e9-5741-b314-6178d5e72bda', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 'Fotoğrafı aldım, şişlik şimdilik bilek çevresinde sınırlı. Ağrı için parasetamol verilebilir; aspirin ve ibuprofen kanamayı artırır, vermeyin.', NULL, true, '2026-08-19T19:57:55.814Z'),
  ('478b2008-8122-5f75-a1c7-f127e57f87da', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'Tamam. Yürüterek indirelim mi, yoksa bekleyelim mi? Telefon çekiyor ama helikopter ister miyiz?', NULL, false, '2026-08-19T19:59:55.814Z'),
  ('76ac6ece-25bc-5a59-8ca9-3d651b9e5b2d', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 'Hastayı yürütmeyin; kas hareketi zehrin yayılmasını hızlandırır. Sırt/sedye ile Ayder’e taşıyın, ben 112’ye konum ve durum bilgisini iletiyorum; ambulans sizi orada karşılasın.', NULL, true, '2026-08-19T20:01:55.814Z'),
  ('5ae08927-853a-59a6-a385-342b0a01f9d4', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'Yola çıktık. 20 dakikadır şişlik aynı, ağrı biraz azaldı. Diş eti kanaması yok.', NULL, false, '2026-08-19T20:18:55.814Z'),
  ('4e2d01f5-76ed-5c44-b064-6e3ea7b0d63e', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '3a6583b4-1296-5d39-aa77-2f8bb89ed9bd', 'İyi haber. Yolda nefes darlığı, dudakta morarma veya diş eti kanaması olursa hemen 112’yi arayın. Hastaneye vardığınızda bu sohbeti acil doktoruna gösterin; antivenom kararı orada verilecek.', NULL, true, '2026-08-19T20:20:55.814Z'),
  ('50b00979-df51-5152-b45a-bc8fcbb6c9d7', 'dc6c1bdc-8ed0-52d4-8c71-632eb2d1c99d', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'Çok teşekkür ederim, ambulans Ayder’de bekliyormuş. Geçmiş olsun dileklerinizi ileteceğim.', NULL, false, '2026-08-19T20:24:55.814Z'),
  ('55c1c533-3239-57e7-98b9-882bcc87cad1', 'ecd0fa4d-47f5-5d83-8ffe-2ff63bbd34ac', '75660a3a-ac38-55a0-be2f-fa317f1404b8', 'Belgrad Ormanı’nda yürüyüşten sonra baldırımda kene buldum, çıkarmalı mıyım?', NULL, false, '2026-07-23T19:47:55.814Z')
