INSERT INTO "news_items" ("id", "category", "title", "summary", "body", "region", "country_code", "coords", "source_name", "source_url", "severity", "published_at", "expires_at") VALUES
  ('e7d69acd-2148-51f0-a2dd-a8d6deb83183', 'weather', 'Kaçkar’da erken kar: 2.500 m üstü için turuncu uyarı', 'MGM, Rize ve Artvin yükseklerinde 48 saat boyunca yoğun kar ve fırtına bekliyor.', 'Meteoroloji Genel Müdürlüğü, Doğu Karadeniz’in yüksek kesimleri için turuncu kodlu uyarı yayımladı. 2.500 metre üstünde 40 cm’ye varan kar, 90 km/s rüzgâr ve görüş mesafesinde ciddi düşüş bekleniyor. Kaçkar zirve rotaları ve Kavron–Deniz Gölü hattı için tırmanış planlarının ertelenmesi öneriliyor. Yaylalarda kalan gruplar için jandarma bilgilendirme yaptı.', 'Kaçkar Dağları, Rize', 'TR', geo_point(41.16, 40.83), 'MGM', 'https://www.mgm.gov.tr', 'critical', '2026-09-06T16:47:55.823Z', '2026-09-08T16:47:55.823Z'),
  ('3618ba7d-ced3-5f23-a547-0f2db7d966e7', 'closure', 'Olimpos-Beydağları Milli Parkı yangın riski nedeniyle 5 gün kapalı', 'Tahtalı ve Çıralı arasındaki tüm patikalar geçici olarak kapatıldı.', 'Milli Parklar Genel Müdürlüğü, aşırı sıcak ve düşük nem nedeniyle Olimpos-Beydağları Milli Parkı’nda tüm yürüyüş parkurlarını ve kamp alanlarını 5 gün süreyle kapattı. Likya Yolu’nun Çıralı–Tekirova etabı bu kapsamda. İhlaller için idari para cezası uygulanacak.', 'Antalya', 'TR', geo_point(30.47, 36.42), 'Milli Parklar', 'https://www.tarimorman.gov.tr/DKMP', 'critical', '2026-09-06T10:47:55.823Z', '2026-09-10T19:47:55.823Z'),
  ('ab6d7726-3d41-5ed5-92dc-5801cf0a3edf', 'rescue', 'AKUT, Aladağlar’da mahsur kalan iki dağcıyı kurtardı', 'Demirkazık kuzey yüzünde gece operasyonu; dağcıların sağlık durumu iyi.', 'AKUT Niğde ekibi, Demirkazık kuzey yüzünde hava bozması nedeniyle ilerleyemeyen iki dağcıya gece 02:40’ta ulaştı. Dağcılar sabah saatlerinde Çukurbağ’a indirildi. AKUT, rota bilgisi ve dönüş saatinin mutlaka yakınlarla paylaşılmasını hatırlattı.', 'Aladağlar, Niğde', 'TR', geo_point(35.15, 37.82), 'AKUT', 'https://www.akut.org.tr', 'warning', '2026-09-06T05:47:55.823Z', NULL),
  ('1b16c083-7367-5d14-96a8-3310406adbd1', 'weather', 'Babadağ’da uçuş yasağı: 50 km/s üstü rüzgâr', 'DHMİ ve Fethiye Kaymakamlığı, yamaç paraşütü uçuşlarını iki gün durdurdu.', 'Babadağ 1.700 ve 1.900 m pistlerinde rüzgâr hızının 50 km/s’yi aşması nedeniyle tandem ve solo uçuşlar askıya alındı. Karar, rüzgâr ölçümlerine göre güncellenecek.', 'Babadağ, Fethiye', 'TR', geo_point(29.19, 36.54), 'DHMİ', 'https://www.dhmi.gov.tr', 'warning', '2026-09-06T13:47:55.823Z', '2026-09-08T11:47:55.823Z'),
  ('0a4d957c-17c8-54c4-8f67-501332f7513e', 'event', 'Kaş Sualtı Festivali bu hafta sonu başlıyor', 'Ücretsiz deneme dalışları, sualtı temizliği ve fotoğraf yarışması.', 'Türkiye Sualtı Sporları Federasyonu ve Kaş Belediyesi’nin düzenlediği festival cumartesi 09:00’da liman meydanında açılıyor. Program: deneme dalışları, Kanyon temizlik dalışı, gece dalışı atölyesi ve pazar günü sualtı fotoğraf yarışması ödül töreni.', 'Kaş, Antalya', 'TR', geo_point(29.64, 36.2), 'TSSF', 'https://www.tssf.gov.tr', 'info', '2026-09-05T19:47:55.823Z', '2026-09-11T19:47:55.823Z'),
  ('5eb6fb49-a431-5237-9666-4c4d8c09a57d', 'gear', 'Yeni çığ transceiver testleri yayınlandı: 3 model öne çıktı', 'Bağımsız test grubu 8 modeli menzil, çoklu gömü ve pil ömrüne göre karşılaştırdı.', 'Türkiye Dağcılık Federasyonu çığ komisyonunun paylaştığı testlerde üç antenli modellerin çoklu gömü senaryolarında belirgin şekilde daha hızlı olduğu görüldü. Rapor; menzil, işaretleme fonksiyonu ve -20 °C pil performansı başlıklarını içeriyor.', 'Türkiye', 'TR', NULL, 'TDF', 'https://tdf.gov.tr', 'info', '2026-09-04T19:47:55.823Z', NULL),
  ('0911bd3d-432c-5da3-b3ee-92b67d928244', 'weather', 'Çoruh’ta su seviyesi yükseldi: rafting parkurunda 4+ derece', 'Baraj salımı ve yağış nedeniyle Yusufeli parkurunda deneyimsiz gruplara uyarı.', 'DSİ verilerine göre Çoruh debisi 48 saatte iki katına çıktı. Rafting operatörleri sadece deneyimli gruplarla çıkış yapıyor; kano ve şişme kayak için parkur önerilmiyor.', 'Yusufeli, Artvin', 'TR', geo_point(41.54, 40.82), 'MGM', 'https://www.mgm.gov.tr', 'warning', '2026-09-05T13:47:55.823Z', '2026-09-07T13:47:55.823Z'),
  ('b531f514-d0bc-5420-875a-5874073c1f68', 'community', 'Likya Yolu’nda 120 km işaretleme yenilendi', 'Gönüllüler Fethiye–Kalkan arasında kırmızı-beyaz işaretleri ve yön tabelalarını yeniledi.', 'Kültür Rotaları Derneği gönüllüleri üç haftada Ölüdeniz’den Kalkan’a kadar olan etabı yeniden işaretledi. Zirtan’dan 34 gönüllü katıldı. Eksik gördüğünüz işaretleri uygulamadan bildirebilirsiniz.', 'Likya Yolu, Muğla', 'TR', geo_point(29.12, 36.55), 'Kültür Rotaları Derneği', 'https://cultureroutesinturkey.com', 'info', '2026-09-03T19:47:55.823Z', NULL),
  ('04e978b0-53e2-5e9c-b3b4-96787957a7a2', 'science', 'Ağrı Dağı buzulu 40 yılda %30 küçüldü', 'Uydu verileriyle yapılan çalışma, zirve buzulunun hızla geri çekildiğini gösteriyor.', 'İTÜ ve Iğdır Üniversitesi araştırmacılarının yayımladığı çalışmaya göre Ağrı Dağı zirve buzulu 1984’ten bu yana yaklaşık %30 alan kaybetti. Çalışma, tırmanış rotalarında çatlak ve düşen taş riskinin arttığını belirtiyor.', 'Ağrı Dağı, Iğdır', 'TR', geo_point(44.3, 39.7), 'İTÜ', 'https://www.itu.edu.tr', 'info', '2026-09-02T19:47:55.823Z', NULL),
  ('61ce66e8-d6eb-5ce9-b854-03615b1e5bf6', 'weather', 'Ege kıyılarında medüz yoğunluğu: dalış ve yüzme için uyarı', 'Bodrum–Datça hattında yakıcı medüz gözlemleri arttı.', 'Sahil Güvenlik ve TSSF, Datça–Bodrum arasında yakıcı medüz (Pelagia noctiluca) yoğunluğunun arttığını duyurdu. Dalış gruplarına tam giysi öneriliyor.', 'Muğla', 'TR', geo_point(27.7, 36.8), 'TSSF', 'https://www.tssf.gov.tr', 'warning', '2026-08-31T19:47:55.823Z', '2026-09-05T19:47:55.823Z'),
  ('b94b290a-7755-540f-9346-dd27dec90a17', 'closure', 'Uludağ teleferiği bakım nedeniyle 3 gün kapalıydı', 'Bakım tamamlandı; seferler yeniden başladı.', 'Uludağ teleferiği yıllık bakım çalışması nedeniyle üç gün hizmet vermedi. Bakımın tamamlanmasıyla seferler normal tarifeye döndü.', 'Uludağ, Bursa', 'TR', geo_point(29.08, 40.1), 'Bursa Büyükşehir', NULL, 'info', '2026-08-28T19:47:55.823Z', '2026-09-01T19:47:55.823Z'),
  ('948ef22d-15b2-58f9-9071-92bc7ff6a61a', 'community', 'Ağrı Dağı tırmanış izinleri artık uygulama üzerinden', 'Valilik, izin başvurularını dijitale taşıdı; 72 saat önceden başvuru gerekiyor.', 'Iğdır Valiliği, Ağrı Dağı tırmanış izinlerinin e-Devlet üzerinden alınacağını duyurdu. Yabancı dağcılar için rehber zorunluluğu sürüyor. Zirtan’dan izin bağlantısına Ağrı destinasyon sayfasından ulaşabilirsiniz.', 'Iğdır', 'TR', geo_point(44.3, 39.7), 'Iğdır Valiliği', 'https://www.igdir.gov.tr', 'info', '2026-08-30T19:47:55.823Z', NULL),
  ('df353688-313b-55f1-a8de-bd30190833a1', 'rescue', 'Everest Ana Kampı rotasında helikopter tahliyeleri arttı', 'Nepal turizm bakanlığı gereksiz tahliyelere karşı sigorta denetimini sıkılaştırdı.', 'Khumbu bölgesinde bu sezon 140’tan fazla helikopter tahliyesi yapıldı. Yetkililer, irtifa hastalığı belirtilerinin ciddiye alınması gerektiğini ancak sigorta suistimallerinin de denetleneceğini açıkladı.', 'Khumbu, Nepal', 'NP', geo_point(86.83, 27.98), 'Nepal Turizm Bakanlığı', 'https://tourism.gov.np', 'info', '2026-09-01T19:47:55.823Z', NULL),
  ('a5f3197b-e491-57ef-982a-97887f89c410', 'closure', 'Kelebekler Vadisi’ne giriş kaya düşmesi nedeniyle kapatılmıştı', 'Şelale patikası 2 hafta kapalı kaldı; yeniden açıldı.', 'Fethiye Kaymakamlığı, kaya düşmesi sonrası Kelebekler Vadisi şelale patikasını iki hafta süreyle kapatmıştı. Jeolojik inceleme sonrası patika yeni koruma ağlarıyla yeniden açıldı.', 'Fethiye, Muğla', 'TR', geo_point(29.13, 36.5), 'Milli Parklar', NULL, 'warning', '2026-08-17T19:47:55.823Z', '2026-08-31T19:47:55.823Z')
INSERT INTO "watch_progress" ("user_id", "program_id", "position_sec", "duration_sec", "updated_at") VALUES
