INSERT INTO "kid_places" ("image_url", "stroller_friendly", "shade", "toilets", "water", "trail_km", "trail_min", "entry_fee_try", "season_months", "linked_business_id", "linked_library_place_id", "country_code", "id", "name", "kind", "age_bands", "coords", "location_name", "description", "facilities", "safety_notes", "rating", "review_count") VALUES
  ('https://images.unsplash.com/photo-1441974231531-c6227db76b6e?auto=format&fit=crop&w=1000&q=80', true, true, true, true, 2.5, 50, 30, '{}', NULL, NULL, 'TR', '725245df-fa59-57b1-af0b-3b2afecba6aa', 'Polonezköy Tabiat Parkı', 'nature_park', '{"0_3","4_6","7_10","11_14"}', geo_point(29.1345, 41.1108), 'Beykoz, İstanbul', 'Şehre en yakın orman parkı. Piknik masaları, ağaçlar arasında kısa yürüyüş döngüsü, küçük oyun alanı ve at binme. Hafta içi sakin, hafta sonu kalabalık.', '{"piknik masası","mangal alanı","oyun alanı","at binme","büfe","otopark"}', '{"Kene riski: uzun pantolon ve dönüşte kontrol","Hafta sonu araç trafiği"}', 4.5, 412),
  ('https://images.unsplash.com/photo-1476611317561-60117649dd94?auto=format&fit=crop&w=1000&q=80', true, true, true, true, 3.2, 60, 0, '{}', NULL, NULL, 'TR', '3038d259-4c33-5072-8648-5b11ee0383df', 'Atatürk Kent Ormanı', 'easy_trail', '{"0_3","4_6","7_10","11_14"}', geo_point(28.9955, 41.1445), 'Sarıyer, İstanbul', 'Asfalt ve stabilize karışık, bebek arabasıyla rahat gezilen orman yolu. Çocuk oyun grupları ve geniş çim alanlar.', '{"oyun alanı","çim alan","kafe","bisiklet kiralama","otopark"}', '{"Bisiklet yolu ile yaya yolu kesişimlerinde dikkat"}', 4.4, 287),
  ('https://images.unsplash.com/photo-1448375240586-882707db888b?auto=format&fit=crop&w=1000&q=80', true, true, true, true, 6, 110, 25, '{}', 'cceb92b2-23ec-5284-973d-33ca80b90c1e', NULL, 'TR', '0288ed59-2107-54e8-aedd-a1bb0a6d6ab8', 'Belgrad Ormanı Neşetsuyu', 'nature_park', '{"0_3","4_6","7_10","11_14"}', geo_point(28.9871, 41.1832), 'Sarıyer, İstanbul', 'Belgrad Ormanı’nın en aile dostu piknik alanı. Gölgeli masalar, dere kenarı, 6 km’lik yürüyüş parkuru ve yakınında kamp alanı.', '{"piknik masası","dere kenarı","oyun alanı","büfe","otopark","kamp"}', '{"Kene riski yüksek: kene maşası taşıyın","Dere taşları kaygan"}', 4.6, 538),
  ('https://images.unsplash.com/photo-1502933691298-84fc14542831?auto=format&fit=crop&w=1000&q=80', true, true, true, false, 1.5, 30, 0, '{}', NULL, NULL, 'TR', 'a55934ab-f3cd-5c33-85cf-b36ee1d368a4', 'Aydos Ormanı Oyun Alanı', 'playground', '{"0_3","4_6","7_10"}', geo_point(29.2338, 40.9331), 'Kartal, İstanbul', 'Orman içinde ahşap oyun grupları, ip parkuru ve göl manzaralı seyir terası. Yaz akşamları serin.', '{"oyun alanı","ip parkuru","seyir terası","kafe","otopark"}', '{"Seyir terasında korkuluk düşük; küçük çocuklar için dikkat"}', 4.3, 196),
  ('https://images.unsplash.com/photo-1470071459604-3b5ec3a7fe05?auto=format&fit=crop&w=1000&q=80', true, true, true, true, 4, 70, 0, '{}', NULL, NULL, 'TR', '9a5303fe-32f2-5afd-956b-e63f6078a197', 'Kemerburgaz Kent Ormanı', 'easy_trail', '{"0_3","4_6","7_10","11_14"}', geo_point(28.9095, 41.1683), 'Eyüpsultan, İstanbul', 'Geniş asfalt yürüyüş yolları, macera parkı ve piknik alanları. Bebek arabası ve denge bisikleti için ideal.', '{"oyun alanı","macera parkı","piknik masası","kafe","otopark","wc"}', '{"Kene riski"}', 4.4, 233),
  ('https://images.unsplash.com/photo-1472214103451-9374bd1c798e?auto=format&fit=crop&w=1000&q=80', true, false, true, true, 12, 180, 0, '{}', NULL, NULL, 'TR', 'cfa16255-f864-5417-86ab-51e9510f409c', 'Eymir Gölü Bisiklet & Yürüyüş', 'easy_trail', '{"4_6","7_10","11_14"}', geo_point(32.8231, 39.8225), 'Çankaya, Ankara', 'Göl çevresinde düz, 12 km’lik araçsız yol. Çocuk bisikleti kiralama, ördekler ve kamp ateşi kokan bir Ankara klasiği.', '{"bisiklet kiralama","kafe","piknik alanı","göl","otopark"}', '{"Göl kıyısı derin; su kenarında kol mesafesi","Güneş: gölge az"}', 4.6, 604),
  ('https://images.unsplash.com/photo-1469474968028-56623f02e42e?auto=format&fit=crop&w=1000&q=80', false, true, true, true, 3, 60, 40, '{}', NULL, NULL, 'TR', '5b90df14-18e3-50cb-82bc-d00888d4deb6', 'Soğuksu Milli Parkı', 'nature_park', '{"0_3","4_6","7_10","11_14"}', geo_point(32.6333, 40.4667), 'Kızılcahamam, Ankara', 'Sarıçam ormanı, kara akbaba gözlem noktası ve serin mola yerleri. Kısa döngü patikalar ve piknik masaları.', '{"piknik masası","kuş gözlem","büfe","otopark","bungalov"}', '{"Kene riski","Öğle güneşi dik; şapka"}', 4.5, 178),
  ('https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1000&q=80', true, true, true, true, 2, 40, 0, '{}', NULL, NULL, 'TR', 'ff121ae7-1e67-5fd9-ab44-04fd8dc59f4b', 'Kültürpark', 'playground', '{"0_3","4_6","7_10","11_14"}', geo_point(27.1436, 38.4315), 'Konak, İzmir', 'Şehir merkezinde devasa park: oyun alanları, lunapark, gölet ve gölgeli yürüyüş yolları. Akşam serinliği için ideal.', '{"oyun alanı","lunapark","gölet","kafe","müze","wc"}', '{"Lunapark kalabalığında çocuğu gözden ayırmayın"}', 4.3, 921),
  ('https://images.unsplash.com/photo-1452421822248-d4c2b47f0c81?auto=format&fit=crop&w=1000&q=80', false, false, true, false, 4, 75, 0, '{2,3,4,5,9,10,11}', NULL, NULL, 'TR', '781b5df1-1911-5096-9b4f-8ea21804ab11', 'İzmir Kuş Cenneti', 'nature_park', '{"4_6","7_10","11_14"}', geo_point(26.9142, 38.5175), 'Çiğli, İzmir', 'Flamingoların evi. Gözlem kuleleri, dürbünle kuş sayma, tuz düzlüklerinde düz yürüyüş. Bahar sabahları en iyisi.', '{"gözlem kulesi","ziyaretçi merkezi","otopark"}', '{"Gölge yok; güneş kremi ve bol su","Sivrisinek: kovucu"}', 4.4, 156),
  ('https://images.unsplash.com/photo-1507525428034-b723cf961d3e?auto=format&fit=crop&w=1000&q=80', true, false, true, true, NULL, NULL, 0, '{4,5,6,7,8,9,10}', '97aa3acc-f9ba-5fe0-80ff-6289919b7482', NULL, 'TR', '534b3b4b-9ec4-547e-bbd7-aa77b7911092', 'Konyaaltı Plajı Beach Park', 'beach', '{"0_3","4_6","7_10","11_14"}', geo_point(30.6503, 36.8725), 'Konyaaltı, Antalya', 'Çakıl plajı, sahil parkı boyunca oyun alanları, duş ve gölgelik. Deniz hızlı derinleşir; kolluk şart.', '{"oyun alanı","duş","gölgelik","kafe","cankurtaran","wc"}', '{"Deniz hızlı derinleşir; kolluk ve yakın takip","Öğle güneşi"}', 4.5, 1340),
  ('https://images.unsplash.com/photo-1432405972618-c60b0225b8f9?auto=format&fit=crop&w=1000&q=80', true, true, true, true, 1.2, 30, 45, '{}', NULL, NULL, 'TR', '46499543-8d82-581f-9c11-1838158a921f', 'Kurşunlu Şelalesi Tabiat Parkı', 'nature_park', '{"0_3","4_6","7_10","11_14"}', geo_point(30.8353, 36.9797), 'Aksu, Antalya', 'Şelale ve göletler etrafında gölgeli, kısa ahşap yürüyüş yolu. Ördekler, kaplumbağalar ve serin bir öğle molası.', '{"piknik masası","büfe","otopark","wc","seyir noktası"}', '{"Islak ahşap yol kaygan","Gölet kenarı korkuluksuz"}', 4.4, 388),
  ('https://images.unsplash.com/photo-1504280390367-361c6d9f38f4?auto=format&fit=crop&w=1000&q=80', false, false, true, true, 6, 120, 650, '{4,5,6,7,8,9,10}', '97aa3acc-f9ba-5fe0-80ff-6289919b7482', 'cur:raft:koprulu', 'TR', 'e3f61e1a-04da-5343-b561-076b1f8fe81e', 'Köprülü Kanyon Aile Raftingi (Sakin Bölüm)', 'adventure_park', '{"7_10","11_14"}', geo_point(31.1897, 37.1979), 'Manavgat, Antalya', 'Kanyonun alt, sakin bölümünde 7+ yaş için 1–2 derece rafting. Can yeleği ve rehber dahil; öğle yemeği nehir kenarında.', '{"rehber","can yeleği","restoran","otopark","soyunma kabini"}', '{"Akıntı: can yeleği çıkarılmaz","Su soğuk; yedek kıyafet","Güneş"}', 4.7, 512),
  ('https://images.unsplash.com/photo-1504198458649-3128b932f49e?auto=format&fit=crop&w=1000&q=80', false, true, true, true, 1.8, 45, 900, '{5,6,7,8,9}', '685905d6-7a92-59e6-8ffa-053ce0e5f26e', 'cur:camp:kabak', 'TR', '485e90ff-64fd-5905-b970-3fb1a118fc42', 'Kabak Koyu Aile Kampı', 'family_camp', '{"4_6","7_10","11_14"}', geo_point(29.1447, 36.4839), 'Kabak, Fethiye', 'Koya bakan bungalov ve çadır alanı. Akşam ateşi, hamak, sabah kısa patika ile koya iniş. Araba en üstte kalır.', '{"bungalov","çadır alanı","restoran","hamak","ateş alanı","duş"}', '{"Koya inen patika dik ve taşlı","Akşam sivrisinek"}', 4.7, 243),
  ('https://images.unsplash.com/photo-1471506480416-7c2f3c5b8b2f?auto=format&fit=crop&w=1000&q=80', true, false, true, true, NULL, NULL, 0, '{5,6,7,8,9,10}', NULL, NULL, 'TR', 'df5b0ed0-c71e-5001-9e0c-84f74ae7e76d', 'Akyaka Kite Plajı (Sığ Kısım)', 'beach', '{"0_3","4_6","7_10","11_14"}', geo_point(28.3245, 37.0466), 'Akyaka, Muğla', 'Yüzlerce metre boyunca diz boyu sığ, ılık deniz. Öğleden sonra rüzgâr çıkar; sabah saatleri bebekler için ideal.', '{"sığ deniz","kafe","şezlong","duş","wc"}', '{"Öğleden sonra rüzgâr ve dalga","Gölge yok"}', 4.6, 477),
  ('https://images.unsplash.com/photo-1508739773434-c26b3d09e071?auto=format&fit=crop&w=1000&q=80', true, true, true, true, 2, 40, 40, '{}', NULL, NULL, 'TR', '806ccce8-57a6-5325-af3d-5176560f3e79', 'Gölcük Tabiat Parkı', 'nature_park', '{"0_3","4_6","7_10","11_14"}', geo_point(31.5992, 40.6522), 'Bolu', 'Göl çevresinde 2 km’lik düz, ahşap korkuluklu yol. Sonbahar renkleri, ördek besleme (yem satılıyor) ve bungalovlar.', '{"göl yolu","bungalov","restoran","piknik masası","otopark","wc"}', '{"Göl kıyısında korkuluğu olmayan bölümler","Kış aylarında buzlanma"}', 4.6, 702),
  ('https://images.unsplash.com/photo-1454496522488-7a8e488e8606?auto=format&fit=crop&w=1000&q=80', true, true, true, true, 7, 120, 45, '{}', NULL, NULL, 'TR', '056c1e88-1467-5b3a-9181-78e55a4f1ad7', 'Abant Gölü Çevre Yolu', 'easy_trail', '{"0_3","4_6","7_10","11_14"}', geo_point(31.2789, 40.6067), 'Mudurnu, Bolu', 'Gölü çevreleyen 7 km asfalt yol; bisiklet ve fayton. Ara ara piknik ve oyun noktaları. Yaz akşamları serin.', '{"bisiklet kiralama","fayton","restoran","piknik","otopark"}', '{"Fayton ve bisiklet trafiği","Kene riski (çimenlik alanlar)"}', 4.5, 855),
  ('https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=1000&q=80', true, true, true, true, 2.6, 50, 20, '{}', NULL, NULL, 'TR', 'bc0b539d-bcee-57e7-a714-f99a9547fb97', 'Poyrazlar Gölü Tabiat Parkı', 'nature_park', '{"0_3","4_6","7_10","11_14"}', geo_point(30.4361, 40.8433), 'Adapazarı, Sakarya', 'Küçük göl etrafında ahşap yürüyüş yolu, ip parkuru ve geniş oyun alanı. İstanbul’dan günübirlik.', '{"oyun alanı","ip parkuru","kano","kafe","piknik","wc"}', '{"Göl kenarında korkuluksuz iskele"}', 4.3, 214),
  ('https://images.unsplash.com/photo-1486870591958-9b9d0d1dda99?auto=format&fit=crop&w=1000&q=80', false, true, true, true, 2, 45, 0, '{}', NULL, 'cur:ski:uludag', 'TR', '29408576-837a-5c03-afbb-f5ed6472e223', 'Uludağ Sarıalan Piknik Alanı', 'nature_park', '{"0_3","4_6","7_10","11_14"}', geo_point(29.1105, 40.1005), 'Uludağ, Bursa', 'Teleferikle çıkılan, çam ormanı içindeki yayla piknik alanı. Yazın serin, kışın kızak. Kısa patikalar ve gözleme.', '{"teleferik","piknik masası","restoran","kızak alanı","wc"}', '{"Hava aniden değişir; kat kat giysi","Kışın kızak pistinde çarpışma"}', 4.4, 633),
