  ('76fdb820-d956-51a1-b685-d59723ab8fca', '2a3fa12e-fd22-56ac-b6a7-fe6ce6b2da9d', '123eb7ed-5eb9-59e7-9cc3-05ae328efcb4', 'text', 'Hafta sonu hava: Marmara güneşli, Karadeniz sağanak, Akdeniz 33°C. Suyunuzu alın 💧', NULL, NULL, NULL, NULL, NULL, NULL, '2026-09-06T18:32:55.729Z'),
  ('0d58d4dc-3865-5497-8d38-d1e593a9f52c', '5b9d6587-8ec0-5b3d-973d-5124637d54ee', '3ab76f29-6c62-5ce7-b20e-70dba73f0545', 'system', 'sys:created:Mert Öztürk', NULL, NULL, NULL, NULL, NULL, NULL, '2026-08-27T18:47:55.729Z'),
